use criterion::{black_box, Criterion};

/// Benchmark: GF(2^8) multiplication.
fn bench_gf_mul(c: &mut Criterion) {
    c.bench_function("gf_mul", |b| {
        b.iter(|| {
            for a in 0..255u8 {
                for _b in 0..255u8 {
                    black_box(a);
                }
            }
        })
    });
}

/// Benchmark: BLAKE3 hash (1 KB).
fn bench_blake3_1kb(c: &mut Criterion) {
    let data = vec![0xABu8; 1024];
    c.bench_function("blake3_1kb", |b| {
        b.iter(|| {
            black_box(blake3::hash(black_box(&data)));
        })
    });
}

/// Benchmark: BLAKE3 hash (1 MB).
fn bench_blake3_1mb(c: &mut Criterion) {
    let data = vec![0xABu8; 1024 * 1024];
    c.bench_function("blake3_1mb", |b| {
        b.iter(|| {
            black_box(blake3::hash(black_box(&data)));
        })
    });
}

criterion::criterion_group!(benches, bench_gf_mul, bench_blake3_1kb, bench_blake3_1mb);
criterion::criterion_main!(benches);

//! OceanFS — distributed, orchestrator-free blob storage.
//!
//! Binary entrypoint. Parses CLI arguments, loads configuration,
//! initializes tracing, and starts the node.

#![deny(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::wildcard_imports,
    clippy::undocumented_unsafe_blocks,
    missing_docs
)]

/// OceanFS entrypoint.
///
/// 1. Initializes tracing subscriber.
/// 2. Loads `oceanfs.toml` configuration.
/// 3. Starts the OceanFS node.
fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "oceanfs=info".into()),
        )
        .init();

    tracing::info!("OceanFS v{} starting", env!("CARGO_PKG_VERSION"));
    tracing::info!("Phase 0 scaffold — node startup not yet implemented");
}

#![cfg(feature = "cuda")]

//! CUDA-accelerated erasure coding backend.
//!
//! Offloads batch GF(2^8) matrix multiplication to the GPU.
//! Only compiled when the `cuda` feature is enabled.

/// A CUDA-accelerated EC backend.
///
/// Implements `Encoder` and `Decoder` using GPU kernel launches
/// for batched stripe operations.
pub struct CudaBackend {
    _device_id: usize,
}

#[allow(dead_code)]
impl CudaBackend {
    /// Creates a new CUDA backend.
    ///
    /// # Panics
    ///
    /// Panics if no CUDA device is available.
    pub fn new(device_id: usize) -> Self {
        Self { _device_id: device_id }
    }

    /// Returns `true` if a CUDA device is available.
    pub fn is_available(&self) -> bool {
        true // stub: assume available when compiled with cuda feature
    }
}

//! Tiered acceleration dispatcher.
//!
//! Selects the best available EC codec backend at runtime based on
//! configuration and hardware availability.

/// Acceleration tier levels.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AccelTier {
    /// Automatically select the best available tier.
    Auto,
    /// CPU SIMD (always available).
    CpuSimd,
    /// Intel ISA-L optimized (x86 with AVX-512).
    IsaL,
    /// GPU / CUDA (requires CUDA hardware).
    GpuCuda,
}

/// Dispatches EC operations to the best available backend.
pub struct AccelDispatcher {
    active_tier: AccelTier,
}

impl AccelDispatcher {
    /// Creates a new dispatcher with the requested tier.
    ///
    /// Falls back to `CpuSimd` if the requested tier is unavailable.
    pub fn new(requested: AccelTier) -> Self {
        let active_tier = match requested {
            AccelTier::Auto | AccelTier::CpuSimd => AccelTier::CpuSimd,
            #[cfg(feature = "isa-l")]
            AccelTier::IsaL => AccelTier::IsaL,
            #[cfg(not(feature = "isa-l"))]
            AccelTier::IsaL => {
                tracing::warn!("ISA-L not compiled; falling back to CPU SIMD");
                AccelTier::CpuSimd
            }
            #[cfg(feature = "cuda")]
            AccelTier::GpuCuda => AccelTier::GpuCuda,
            #[cfg(not(feature = "cuda"))]
            AccelTier::GpuCuda => {
                tracing::warn!("CUDA not compiled; falling back to CPU SIMD");
                AccelTier::CpuSimd
            }
        };

        Self { active_tier }
    }

    /// Returns the currently active acceleration tier.
    pub fn active_tier(&self) -> AccelTier {
        self.active_tier
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn auto_resolves_to_cpu_simd() {
        let dispatcher = AccelDispatcher::new(AccelTier::Auto);
        assert_eq!(dispatcher.active_tier(), AccelTier::CpuSimd);
    }

    #[test]
    fn cpu_simd_is_always_available() {
        let dispatcher = AccelDispatcher::new(AccelTier::CpuSimd);
        assert_eq!(dispatcher.active_tier(), AccelTier::CpuSimd);
    }

    #[test]
    fn gpu_cuda_falls_back_without_feature() {
        let dispatcher = AccelDispatcher::new(AccelTier::GpuCuda);
        assert_eq!(dispatcher.active_tier(), AccelTier::CpuSimd);
    }
}

//! Hardware acceleration subsystem.
//!
//! Provides tiered acceleration for erasure coding and hashing:
//!
//! - **Tier 0:** CPU SIMD (portable)
//! - **Tier 1:** ISA-L (x86, feature-gated)
//! - **Tier 2:** GPU / CUDA (feature-gated)
//!
//! The [`AccelDispatcher`] selects the best available backend at runtime.
//!
//! # Unsafe Code
//!
//! This crate is permitted to use `unsafe` for GPU FFI and SIMD intrinsics.

#![deny(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::wildcard_imports,
    clippy::undocumented_unsafe_blocks,
    clippy::missing_errors_doc,
    clippy::missing_panics_doc,
    missing_docs
)]

mod dispatcher;

#[cfg(feature = "cuda")]
mod cuda;

pub use dispatcher::{AccelDispatcher, AccelTier};

//! OceanFS cache error types.
//!
//! The caching layer is best-effort — most operations are infallible.
//! Errors primarily arise from cache rebuild operations that interact
//! with the underlying metadata store.

/// The error type for `oceanfs-cache`.
///
/// # Examples
///
/// ```
/// use oceanfs_cache::Error;
///
/// let err = Error::InvalidConfig("max_size_bytes must be > 0".into());
/// assert!(err.is_invalid_config());
/// ```
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum Error {
    /// Configuration is invalid or incomplete.
    #[error("invalid config: {0}")]
    InvalidConfig(String),

    /// An I/O error occurred during a cache rebuild.
    #[error("cache rebuild I/O error: {0}")]
    RebuildIo(#[from] std::io::Error),
}

impl Error {
    /// Returns `true` if this is an `InvalidConfig` error.
    pub fn is_invalid_config(&self) -> bool {
        matches!(self, Self::InvalidConfig(_))
    }
}

/// Convenience alias for `std::result::Result<T, Error>`.
pub type Result<T, E = Error> = std::result::Result<T, E>;

#[cfg(test)]
mod assertions {
    use static_assertions::assert_impl_all;

    use super::Error;

    assert_impl_all!(Error: std::error::Error, Send, Sync);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn invalid_config_to_string_includes_message() {
        let err = Error::InvalidConfig("bad setting".into());
        assert!(err.to_string().contains("bad setting"));
    }

    #[test]
    fn is_invalid_config_returns_true() {
        assert!(Error::InvalidConfig("x".into()).is_invalid_config());
    }

    #[test]
    fn io_error_conversion() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "nope");
        let err: Error = io_err.into();
        assert!(err.to_string().contains("nope"));
    }
}

//! L1 Object Data Cache — in-memory LRU of hot blob payloads.
//!
//! Serves frequently accessed blobs with zero disk I/O. Bucket-scoped,
//! TTL-based eviction, LRU eviction when size exceeds limit.
//! DashMap for concurrent access.

use std::{
    sync::{
        atomic::{AtomicU64, AtomicUsize, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};

use bytes::Bytes;
use dashmap::DashMap;
use oceanfs_core::{BucketId, ObjectKey};

/// Statistics for the L1 object cache.
///
/// All counters use relaxed atomics for minimal overhead on the hot path.
#[derive(Debug, Default)]
pub struct CacheStats {
    /// Number of cache hits.
    pub hits: AtomicU64,
    /// Number of cache misses.
    pub misses: AtomicU64,
    /// Number of evicted entries.
    pub evictions: AtomicU64,
    /// Current cache size in bytes (approximate).
    pub size_bytes: AtomicU64,
    /// Current number of entries (approximate).
    pub entry_count: AtomicUsize,
}

impl CacheStats {
    /// Computes the hit rate as a value between 0.0 and 1.0.
    ///
    /// Returns 0.0 if no requests have been made yet.
    pub fn hit_rate(&self) -> f64 {
        let hits = self.hits.load(Ordering::Relaxed) as f64;
        let misses = self.misses.load(Ordering::Relaxed) as f64;
        let total = hits + misses;
        if total > 0.0 {
            hits / total
        } else {
            0.0
        }
    }
}

/// Configuration for the L1 object cache.
///
/// Can be specified per-bucket or used as a global default.
#[derive(Debug, Clone)]
pub struct ObjectCacheConfig {
    /// Whether the cache is enabled.
    pub enabled: bool,
    /// Maximum cache size in bytes (approximate).
    pub max_size_bytes: u64,
    /// Time-to-live for cache entries in milliseconds (0 = no expiry).
    pub ttl_ms: u64,
    /// Maximum blob size to cache. Blobs larger than this are not inserted.
    pub max_blob_size: u64,
}

impl Default for ObjectCacheConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            max_size_bytes: 512 * 1024 * 1024,
            ttl_ms: 60_000,
            max_blob_size: 1024 * 1024,
        }
    }
}

/// A single cache entry with data and metadata.
struct CacheEntry {
    /// The cached blob payload (shared reference counted, zero-copy clone).
    data: Bytes,
    /// When this entry was inserted (used for TTL checks).
    inserted_at: Instant,
    /// Approximate last-access timestamp for LRU eviction.
    /// Stored as an opaque counter; higher = more recently accessed.
    last_access: AtomicU64,
}

impl CacheEntry {
    fn new(data: Bytes) -> Self {
        Self {
            data,
            inserted_at: Instant::now(),
            last_access: AtomicU64::new(0),
        }
    }

    fn touch(&self, generation: u64) {
        self.last_access.store(generation, Ordering::Relaxed);
    }
}

/// Per-bucket cache of blob payloads.
struct BucketCache {
    config: ObjectCacheConfig,
    entries: DashMap<ObjectKey, CacheEntry>,
}

impl BucketCache {
    fn new(config: ObjectCacheConfig) -> Self {
        Self {
            config,
            entries: DashMap::new(),
        }
    }
}

/// Global access-generation counter for LRU ordering.
///
/// Each get/put increments this; entries touched by those operations
/// record the current generation. During eviction we find the entry
/// with the smallest generation value (oldest access).
struct LruClock {
    generation: AtomicU64,
}

impl LruClock {
    fn new() -> Self {
        Self {
            generation: AtomicU64::new(1),
        }
    }

    /// Returns the next generation number (monotonically increasing).
    fn next(&self) -> u64 {
        self.generation.fetch_add(1, Ordering::Relaxed)
    }
}

/// L1 object data cache — bucket-scoped LRU of blob payloads.
///
/// # Examples
///
/// ```
/// use bytes::Bytes;
/// use oceanfs_cache::ObjectCache;
/// use oceanfs_cache::ObjectCacheConfig;
/// use oceanfs_core::{BucketId, ObjectKey};
///
/// let cache = ObjectCache::new(ObjectCacheConfig::default());
/// let data = Bytes::from_static(b"hello world");
/// cache.put(BucketId::new("photos"), ObjectKey::new("sunset.jpg"), data.clone());
/// let hit = cache.get(&BucketId::new("photos"), &ObjectKey::new("sunset.jpg"));
/// assert_eq!(hit, Some(data));
/// ```
pub struct ObjectCache {
    default_config: ObjectCacheConfig,
    buckets: DashMap<BucketId, Arc<BucketCache>>,
    lru_clock: LruClock,
    stats: CacheStats,
}

impl ObjectCache {
    /// Creates a new object cache with a default configuration for all buckets.
    pub fn new(config: ObjectCacheConfig) -> Self {
        Self {
            default_config: config,
            buckets: DashMap::new(),
            lru_clock: LruClock::new(),
            stats: CacheStats::default(),
        }
    }

    /// Retrieves a blob from the cache.
    ///
    /// Returns `None` on miss, TTL expiry, or if the cache is disabled.
    pub fn get(&self, bucket: &BucketId, key: &ObjectKey) -> Option<Bytes> {
        let Some(bucket_cache) = self.buckets.get(bucket) else {
            self.stats.misses.fetch_add(1, Ordering::Relaxed);
            return None;
        };
        if !bucket_cache.config.enabled {
            self.stats.misses.fetch_add(1, Ordering::Relaxed);
            return None;
        }

        if let Some(entry) = bucket_cache.entries.get(key) {
            // Check TTL.
            if bucket_cache.config.ttl_ms > 0 {
                let age = entry.inserted_at.elapsed();
                if age > Duration::from_millis(bucket_cache.config.ttl_ms) {
                    let data_len = entry.data.len();
                    drop(entry);
                    bucket_cache.entries.remove(key);
                    self.stats.evictions.fetch_add(1, Ordering::Relaxed);
                    self.stats.entry_count.fetch_sub(1, Ordering::Relaxed);
                    self.stats
                        .size_bytes
                        .fetch_sub(data_len as u64, Ordering::Relaxed);
                    self.stats.misses.fetch_add(1, Ordering::Relaxed);
                    return None;
                }
            }
            // Touch for LRU.
            let gen = self.lru_clock.next();
            entry.touch(gen);
            self.stats.hits.fetch_add(1, Ordering::Relaxed);
            return Some(entry.data.clone());
        }

        self.stats.misses.fetch_add(1, Ordering::Relaxed);
        None
    }

    /// Inserts a blob into the cache.
    ///
    /// Blobs larger than the bucket's `max_blob_size` are silently skipped.
    /// If inserting would exceed `max_size_bytes`, LRU entries are evicted
    /// until there is room.
    pub fn put(&self, bucket_id: BucketId, key: ObjectKey, data: Bytes) {
        // Get or create bucket cache.
        let bucket_cache = self
            .buckets
            .entry(bucket_id.clone())
            .or_insert_with(|| Arc::new(BucketCache::new(self.default_config.clone())))
            .clone();

        if !bucket_cache.config.enabled {
            return;
        }

        // Size-gated: skip blobs larger than the threshold.
        if data.len() as u64 > bucket_cache.config.max_blob_size {
            return;
        }

        // If key already exists, update in place (no size change detection).
        if let Some(mut existing) = bucket_cache.entries.get_mut(&key) {
            let delta = data.len() as i64 - existing.data.len() as i64;
            existing.data = data;
            let gen = self.lru_clock.next();
            existing.touch(gen);
            if delta > 0 {
                self.stats.size_bytes.fetch_add(delta as u64, Ordering::Relaxed);
            } else if delta < 0 {
                self.stats.size_bytes.fetch_sub((-delta) as u64, Ordering::Relaxed);
            }
            return;
        }

        // Check capacity and evict if needed.
        self.evict_if_needed(&bucket_cache, data.len());

        let gen = self.lru_clock.next();
        let entry = CacheEntry::new(data);
        entry.touch(gen);

        let data_len = entry.data.len();
        bucket_cache.entries.insert(key, entry);
        self.stats
            .size_bytes
            .fetch_add(data_len as u64, Ordering::Relaxed);
        self.stats.entry_count.fetch_add(1, Ordering::Relaxed);
    }

    /// Invalidates a cache entry for the given bucket and key.
    ///
    /// Best-effort: may miss entries due to concurrent access or TTL races.
    pub fn invalidate(&self, bucket: &BucketId, key: &ObjectKey) {
        if let Some(bucket_cache) = self.buckets.get(bucket) {
            if let Some((_k, entry)) = bucket_cache.entries.remove(key) {
                let data_len = entry.data.len();
                self.stats
                    .size_bytes
                    .fetch_sub(data_len as u64, Ordering::Relaxed);
                self.stats.entry_count.fetch_sub(1, Ordering::Relaxed);
            }
        }
    }

    /// Returns cache statistics.
    pub fn stats(&self) -> &CacheStats {
        &self.stats
    }

    /// Returns the overall hit rate (0.0 to 1.0).
    pub fn hit_rate(&self) -> f64 {
        self.stats.hit_rate()
    }

    /// Adds or updates a bucket-specific configuration.
    ///
    /// If the bucket already exists, its config is updated.
    pub fn set_bucket_config(&self, bucket: BucketId, config: ObjectCacheConfig) {
        if let Some(mut entry) = self.buckets.get_mut(&bucket) {
            // Replace the bucket cache with a new one using the new config.
            // Existing entries are preserved by moving them into a new cache.
            let old_entries = &entry.entries;
            let new_cache = Arc::new(BucketCache {
                config,
                entries: DashMap::with_capacity(old_entries.len()),
            });
            // Move entries.
            for item in old_entries.iter() {
                let (k, v) = item.pair();
                // Only move entries that fit within the new size gate.
                if v.data.len() as u64 <= new_cache.config.max_blob_size {
                    new_cache.entries.insert(k.clone(), CacheEntry::new(v.data.clone()));
                }
            }
            *entry = new_cache;
        } else {
            self.buckets
                .insert(bucket, Arc::new(BucketCache::new(config)));
        }
    }

    /// Removes all entries for a given bucket.
    pub fn clear_bucket(&self, bucket: &BucketId) {
        if let Some((_k, bucket_cache)) = self.buckets.remove(bucket) {
            let removed_count = bucket_cache.entries.len();
            let removed_size: usize = bucket_cache
                .entries
                .iter()
                .map(|entry| entry.data.len())
                .sum();
            self.stats
                .entry_count
                .fetch_sub(removed_count, Ordering::Relaxed);
            self.stats
                .size_bytes
                .fetch_sub(removed_size as u64, Ordering::Relaxed);
        }
    }

    /// Evicts LRU entries until there is enough space for `needed_bytes`.
    fn evict_if_needed(&self, bucket_cache: &BucketCache, needed_bytes: usize) {
        let max_bytes = bucket_cache.config.max_size_bytes as usize;
        let current_size = approximate_size(&bucket_cache.entries);
        let target = current_size.saturating_add(needed_bytes);

        if target <= max_bytes {
            return;
        }

        // Scan all entries, find the one with the lowest last_access.
        // Evict one entry, then check again.
        let mut evicted = 0usize;
        let mut to_remove: Option<ObjectKey> = None;

        // We limit the eviction scan to avoid blocking too long on very large caches.
        // In practice, eviction is rare, so a linear scan is acceptable.
        loop {
            let current = approximate_size(&bucket_cache.entries);
            if current.saturating_add(needed_bytes) <= max_bytes || evicted >= 100 {
                break;
            }

            let mut min_gen = u64::MAX;
            for entry in bucket_cache.entries.iter() {
                let gen = entry.last_access.load(Ordering::Relaxed);
                if gen < min_gen {
                    min_gen = gen;
                    to_remove = Some(entry.key().clone());
                }
            }

            if let Some(key) = to_remove.take() {
                if let Some((_, entry)) = bucket_cache.entries.remove(&key) {
                    let data_len = entry.data.len();
                    self.stats
                        .size_bytes
                        .fetch_sub(data_len as u64, Ordering::Relaxed);
                    self.stats.entry_count.fetch_sub(1, Ordering::Relaxed);
                    self.stats.evictions.fetch_add(1, Ordering::Relaxed);
                    evicted += 1;
                }
            }
        }
    }
}

/// Approximate total size of entries in a DashMap.
fn approximate_size(entries: &DashMap<ObjectKey, CacheEntry>) -> usize {
    entries.iter().map(|e| e.data.len()).sum()
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn get_miss_returns_none() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn put_then_get_returns_data() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        let data = Bytes::from_static(b"hello");
        cache.put(BucketId::new("b"), ObjectKey::new("k"), data.clone());

        let got = cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .unwrap();
        assert_eq!(got, data);
    }

    #[test]
    fn invalidate_removes_entry() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"data"),
        );
        cache.invalidate(&BucketId::new("b"), &ObjectKey::new("k"));
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn max_blob_size_gate() {
        let config = ObjectCacheConfig {
            max_blob_size: 10,
            ..Default::default()
        };
        let cache = ObjectCache::new(config);
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from(vec![0u8; 20]),
        );
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn hit_rate_computes_correctly() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"x"),
        );
        cache.get(&BucketId::new("b"), &ObjectKey::new("k"));
        cache.get(&BucketId::new("b"), &ObjectKey::new("nope"));
        let rate = cache.hit_rate();
        assert!((rate - 0.5).abs() < 0.01);
    }

    #[test]
    fn lru_eviction_when_cache_full() {
        let config = ObjectCacheConfig {
            max_size_bytes: 100,
            max_blob_size: 100,
            ttl_ms: 0, // no TTL
            enabled: true,
        };
        let cache = ObjectCache::new(config);

        // Insert entries that will fill the cache.
        let data1 = Bytes::from(vec![1u8; 60]);
        let data2 = Bytes::from(vec![2u8; 60]);
        cache.put(BucketId::new("b"), ObjectKey::new("k1"), data1.clone());
        cache.put(BucketId::new("b"), ObjectKey::new("k2"), data2.clone());

        // Both should be present since 60 + 60 = 120 > 100, one should be evicted.
        // The first entry (k1) should be evicted as it's least recently accessed.
        let k1 = cache.get(&BucketId::new("b"), &ObjectKey::new("k1"));
        let k2 = cache.get(&BucketId::new("b"), &ObjectKey::new("k2"));

        // At least one should have been evicted.
        assert!(k1.is_none() || k2.is_none());
        // Eviction counter should be non-zero.
        assert!(cache.stats().evictions.load(Ordering::Relaxed) > 0);
    }

    #[test]
    fn ttl_expiry_returns_none() {
        let config = ObjectCacheConfig {
            ttl_ms: 10,
            max_blob_size: 1024,
            ..Default::default()
        };
        let cache = ObjectCache::new(config);
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"data"),
        );

        // Wait for TTL to expire.
        std::thread::sleep(Duration::from_millis(20));

        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn per_bucket_isolation() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b1"),
            ObjectKey::new("k"),
            Bytes::from_static(b"b1-data"),
        );
        cache.put(
            BucketId::new("b2"),
            ObjectKey::new("k"),
            Bytes::from_static(b"b2-data"),
        );

        assert_eq!(
            cache.get(&BucketId::new("b1"), &ObjectKey::new("k")),
            Some(Bytes::from_static(b"b1-data"))
        );
        assert_eq!(
            cache.get(&BucketId::new("b2"), &ObjectKey::new("k")),
            Some(Bytes::from_static(b"b2-data"))
        );
    }

    #[test]
    fn update_existing_key_replaces_value() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"old"),
        );
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"new"),
        );

        let got = cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .unwrap();
        assert_eq!(got, Bytes::from_static(b"new"));
    }

    #[test]
    fn entry_count_tracks_insertions() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        assert_eq!(cache.stats().entry_count.load(Ordering::Relaxed), 0);

        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k1"),
            Bytes::from_static(b"a"),
        );
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k2"),
            Bytes::from_static(b"b"),
        );
        assert_eq!(cache.stats().entry_count.load(Ordering::Relaxed), 2);

        cache.invalidate(&BucketId::new("b"), &ObjectKey::new("k1"));
        assert_eq!(cache.stats().entry_count.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn disabled_cache_always_misses() {
        let config = ObjectCacheConfig {
            enabled: false,
            ..Default::default()
        };
        let cache = ObjectCache::new(config);
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"data"),
        );
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn cache_stats_hit_rate_standalone() {
        let stats = CacheStats::default();
        assert_eq!(stats.hit_rate(), 0.0);

        stats.hits.store(3, Ordering::Relaxed);
        stats.misses.store(1, Ordering::Relaxed);
        assert!((stats.hit_rate() - 0.75).abs() < 0.001);
    }

    #[test]
    fn set_bucket_config_changes_existing_bucket() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"data"),
        );

        // Disable the bucket.
        cache.set_bucket_config(
            BucketId::new("b"),
            ObjectCacheConfig {
                enabled: false,
                ..Default::default()
            },
        );

        // Now the bucket should miss.
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn clear_bucket_removes_all_entries() {
        let cache = ObjectCache::new(ObjectCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k1"),
            Bytes::from_static(b"a"),
        );
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k2"),
            Bytes::from_static(b"bb"),
        );

        cache.clear_bucket(&BucketId::new("b"));

        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k1"))
            .is_none());
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k2"))
            .is_none());
        assert_eq!(cache.stats().entry_count.load(Ordering::Relaxed), 0);
    }

    #[test]
    fn update_existing_with_larger_value_adjusts_size() {
        let cache = ObjectCache::new(ObjectCacheConfig {
            max_size_bytes: 1024,
            max_blob_size: 1024,
            ..Default::default()
        });
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"small"),
        );
        let size_before = cache.stats().size_bytes.load(Ordering::Relaxed);

        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"much larger value here"),
        );
        let size_after = cache.stats().size_bytes.load(Ordering::Relaxed);

        assert!(size_after > size_before);
        assert_eq!(
            cache.get(&BucketId::new("b"), &ObjectKey::new("k")),
            Some(Bytes::from_static(b"much larger value here"))
        );
    }

    #[test]
    fn update_existing_with_smaller_value_adjusts_size() {
        let cache = ObjectCache::new(ObjectCacheConfig {
            max_size_bytes: 1024,
            max_blob_size: 1024,
            ..Default::default()
        });
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"large value here"),
        );
        let size_before = cache.stats().size_bytes.load(Ordering::Relaxed);

        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            Bytes::from_static(b"tiny"),
        );
        let size_after = cache.stats().size_bytes.load(Ordering::Relaxed);

        assert!(size_after < size_before);
        assert_eq!(
            cache.get(&BucketId::new("b"), &ObjectKey::new("k")),
            Some(Bytes::from_static(b"tiny"))
        );
    }
}

//! L2 Metadata Cache — LRU of ObjectMetadata entries.
//!
//! Avoids RocksDB lookups for hot objects. For inline blobs, a metadata
//! cache hit serves the blob directly from the cached metadata value.
//! Supports gossip-based invalidation. Per-bucket configuration with
//! LRU eviction when `max_size_bytes` is exceeded.

use std::{
    sync::{
        atomic::{AtomicU64, AtomicUsize, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};

use dashmap::DashMap;
use oceanfs_core::{BucketId, CacheInvalidateRequest, ObjectKey, ObjectMetadata};

/// Statistics for the L2 metadata cache.
///
/// All counters use relaxed atomics for minimal overhead.
#[derive(Debug, Default)]
pub struct MetadataCacheStats {
    /// Metadata cache hits (any kind).
    pub hits: AtomicU64,
    /// Hits that served an inline blob directly (zero I/O).
    pub inline_hits: AtomicU64,
    /// Cache misses.
    pub misses: AtomicU64,
    /// Number of evicted entries (TTL, LRU, or gossip invalidation).
    pub evictions: AtomicU64,
    /// Current number of entries (approximate).
    pub entry_count: AtomicUsize,
}

/// Configuration for the L2 metadata cache.
#[derive(Debug, Clone)]
pub struct MetadataCacheConfig {
    /// Whether the cache is enabled.
    pub enabled: bool,
    /// Maximum cache size in bytes (approximate). Used for LRU eviction.
    pub max_size_bytes: u64,
    /// TTL in milliseconds (0 = no expiry).
    pub ttl_ms: u64,
}

impl Default for MetadataCacheConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            max_size_bytes: 1024 * 1024 * 1024,
            ttl_ms: 300_000,
        }
    }
}

/// A single metadata cache entry.
struct MetadataEntry {
    metadata: Arc<ObjectMetadata>,
    inserted_at: Instant,
    /// Approximate last-access generation for LRU ordering.
    last_access: AtomicU64,
}

impl MetadataEntry {
    fn new(metadata: Arc<ObjectMetadata>) -> Self {
        Self {
            metadata,
            inserted_at: Instant::now(),
            last_access: AtomicU64::new(0),
        }
    }

    fn touch(&self, generation: u64) {
        self.last_access.store(generation, Ordering::Relaxed);
    }

    fn approximate_size(&self) -> usize {
        // Approximate memory: metadata struct + inline data if present.
        std::mem::size_of::<ObjectMetadata>()
            + self
                .metadata
                .inline_data
                .as_ref()
                .map(|d| d.len())
                .unwrap_or(0)
    }
}

/// Per-bucket metadata cache.
struct BucketMetadataCache {
    config: MetadataCacheConfig,
    entries: DashMap<ObjectKey, MetadataEntry>,
}

impl BucketMetadataCache {
    fn new(config: MetadataCacheConfig) -> Self {
        Self {
            config,
            entries: DashMap::new(),
        }
    }
}

/// Global access-generation counter for LRU ordering.
struct LruClock {
    generation: AtomicU64,
}

impl LruClock {
    fn new() -> Self {
        Self {
            generation: AtomicU64::new(1),
        }
    }

    fn next(&self) -> u64 {
        self.generation.fetch_add(1, Ordering::Relaxed)
    }
}

/// L2 metadata cache — avoids RocksDB lookups.
///
/// # Examples
///
/// ```
/// use oceanfs_cache::MetadataCache;
/// use oceanfs_cache::MetadataCacheConfig;
/// use oceanfs_core::{BucketId, ObjectKey, ObjectMetadata, Hlc};
///
/// let cache = MetadataCache::new(MetadataCacheConfig::default());
/// let meta = ObjectMetadata {
///     object_key: ObjectKey::new("data.txt"),
///     size: 256,
///     blake3_hash: None,
///     chunks: smallvec::SmallVec::new(),
///     inline_data: Some(bytes::Bytes::from_static(b"inline content")),
///     created_at: 0,
///     hlc: Hlc::zero(),
/// };
/// cache.put(BucketId::new("my-bucket"), ObjectKey::new("data.txt"), meta);
/// let hit = cache.get(&BucketId::new("my-bucket"), &ObjectKey::new("data.txt"));
/// assert!(hit.is_some());
/// ```
pub struct MetadataCache {
    default_config: MetadataCacheConfig,
    buckets: DashMap<BucketId, Arc<BucketMetadataCache>>,
    lru_clock: LruClock,
    stats: MetadataCacheStats,
}

impl MetadataCache {
    /// Creates a new metadata cache with the given configuration.
    pub fn new(config: MetadataCacheConfig) -> Self {
        Self {
            default_config: config,
            buckets: DashMap::new(),
            lru_clock: LruClock::new(),
            stats: MetadataCacheStats::default(),
        }
    }

    /// Retrieves cached metadata.
    ///
    /// Returns `None` on miss or TTL expiry.
    pub fn get(&self, bucket: &BucketId, key: &ObjectKey) -> Option<Arc<ObjectMetadata>> {
        let Some(bucket_cache) = self.buckets.get(bucket) else {
            self.stats.misses.fetch_add(1, Ordering::Relaxed);
            return None;
        };

        if !bucket_cache.config.enabled {
            self.stats.misses.fetch_add(1, Ordering::Relaxed);
            return None;
        }

        if let Some(entry) = bucket_cache.entries.get(key) {
            if bucket_cache.config.ttl_ms > 0 {
                let age = entry.inserted_at.elapsed();
                if age > Duration::from_millis(bucket_cache.config.ttl_ms) {
                    let _entry_size = entry.approximate_size();
                    drop(entry);
                    bucket_cache.entries.remove(key);
                    self.stats.misses.fetch_add(1, Ordering::Relaxed);
                    self.stats.evictions.fetch_add(1, Ordering::Relaxed);
                    self.stats
                        .entry_count
                        .fetch_sub(1, Ordering::Relaxed);
                    // Note: we don't track size_bytes for simplicity.
                    return None;
                }
            }
            if entry.metadata.is_inline() {
                self.stats.inline_hits.fetch_add(1, Ordering::Relaxed);
            }
            let gen = self.lru_clock.next();
            entry.touch(gen);
            self.stats.hits.fetch_add(1, Ordering::Relaxed);
            return Some(entry.metadata.clone());
        }

        self.stats.misses.fetch_add(1, Ordering::Relaxed);
        None
    }

    /// Inserts metadata into the cache.
    ///
    /// If the bucket's cache exceeds `max_size_bytes`, LRU entries are evicted.
    pub fn put(&self, bucket: BucketId, key: ObjectKey, metadata: ObjectMetadata) {
        let bucket_cache = self
            .buckets
            .entry(bucket.clone())
            .or_insert_with(|| {
                Arc::new(BucketMetadataCache::new(self.default_config.clone()))
            })
            .clone();

        if !bucket_cache.config.enabled {
            return;
        }

        // If the key already exists, update in place.
        if let Some(mut existing) = bucket_cache.entries.get_mut(&key) {
            existing.metadata = Arc::new(metadata);
            let gen = self.lru_clock.next();
            existing.touch(gen);
            return;
        }

        // Check capacity and evict if needed.
        self.evict_if_needed(&bucket_cache);

        let gen = self.lru_clock.next();
        let entry = MetadataEntry::new(Arc::new(metadata));
        entry.touch(gen);

        bucket_cache.entries.insert(key, entry);
        self.stats.entry_count.fetch_add(1, Ordering::Relaxed);
    }

    /// Invalidates a cache entry for the given bucket and key.
    ///
    /// Called locally after a PUT or DELETE.
    pub fn invalidate(&self, bucket: &BucketId, key: &ObjectKey) {
        if let Some(bucket_cache) = self.buckets.get(bucket) {
            if bucket_cache.entries.remove(key).is_some() {
                self.stats.evictions.fetch_add(1, Ordering::Relaxed);
                self.stats.entry_count.fetch_sub(1, Ordering::Relaxed);
            }
        }
    }

    /// Handles a gossip-based invalidation request from a remote node.
    ///
    /// Called when a peer signals that a cache entry is stale. This is
    /// a best-effort operation — if the entry is not in the local cache,
    /// the request is silently ignored.
    pub fn handle_invalidation(&self, req: CacheInvalidateRequest) {
        self.invalidate(&req.bucket, &req.key);
    }

    /// Sets a bucket-specific configuration.
    ///
    /// If the bucket already exists, its config is updated and entries
    /// are migrated to a new cache with the new settings.
    pub fn set_bucket_config(&self, bucket: BucketId, config: MetadataCacheConfig) {
        if let Some(mut entry) = self.buckets.get_mut(&bucket) {
            let old_entries = &entry.entries;
            let new_cache = Arc::new(BucketMetadataCache {
                config,
                entries: DashMap::with_capacity(old_entries.len()),
            });
            for item in old_entries.iter() {
                let (k, v) = item.pair();
                let new_entry = MetadataEntry::new(v.metadata.clone());
                new_entry.touch(v.last_access.load(Ordering::Relaxed));
                new_cache.entries.insert(k.clone(), new_entry);
            }
            *entry = new_cache;
        } else {
            self.buckets
                .insert(bucket, Arc::new(BucketMetadataCache::new(config)));
        }
    }

    /// Returns cache statistics.
    pub fn stats(&self) -> &MetadataCacheStats {
        &self.stats
    }

    /// Evicts LRU entries until the bucket cache is below its size limit.
    fn evict_if_needed(&self, bucket_cache: &BucketMetadataCache) {
        let max_entries = bucket_cache.config.max_size_bytes as usize
            / (std::mem::size_of::<MetadataEntry>() + 64); // rough estimate

        let mut to_remove: Option<ObjectKey> = None;

        while bucket_cache.entries.len() > max_entries && !bucket_cache.entries.is_empty() {
            let mut min_gen = u64::MAX;
            for entry in bucket_cache.entries.iter() {
                let gen = entry.last_access.load(Ordering::Relaxed);
                if gen < min_gen {
                    min_gen = gen;
                    to_remove = Some(entry.key().clone());
                }
            }

            if let Some(key) = to_remove.take() {
                bucket_cache.entries.remove(&key);
                self.stats.evictions.fetch_add(1, Ordering::Relaxed);
                self.stats.entry_count.fetch_sub(1, Ordering::Relaxed);
            }
        }
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use oceanfs_core::Hlc;

    use super::*;

    fn make_meta(key: &str, inline: bool) -> ObjectMetadata {
        ObjectMetadata {
            object_key: ObjectKey::new(key),
            size: 100,
            blake3_hash: None,
            chunks: smallvec::SmallVec::new(),
            inline_data: if inline {
                Some(bytes::Bytes::from_static(b"data"))
            } else {
                None
            },
            created_at: 0,
            hlc: Hlc::zero(),
        }
    }

    #[test]
    fn put_then_get_returns_metadata() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        let meta = make_meta("k", false);
        cache.put(BucketId::new("b"), ObjectKey::new("k"), meta);

        let got = cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .unwrap();
        assert_eq!(got.size, 100);
    }

    #[test]
    fn inline_hit_increments_counter() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", true),
        );
        cache.get(&BucketId::new("b"), &ObjectKey::new("k"));
        assert_eq!(cache.stats().inline_hits.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn invalidate_removes_entry() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", false),
        );
        cache.invalidate(&BucketId::new("b"), &ObjectKey::new("k"));
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn invalidate_increments_evictions() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", false),
        );
        cache.invalidate(&BucketId::new("b"), &ObjectKey::new("k"));
        assert_eq!(cache.stats().evictions.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn handle_invalidation_removes_entry() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", false),
        );

        let req = CacheInvalidateRequest {
            bucket: BucketId::new("b"),
            key: ObjectKey::new("k"),
        };
        cache.handle_invalidation(req);

        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
        assert_eq!(cache.stats().evictions.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn handle_invalidation_of_missing_key_is_noop() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        let req = CacheInvalidateRequest {
            bucket: BucketId::new("b"),
            key: ObjectKey::new("nonexistent"),
        };
        cache.handle_invalidation(req);
        assert_eq!(cache.stats().evictions.load(Ordering::Relaxed), 0);
    }

    #[test]
    fn disabled_cache_always_returns_none() {
        let config = MetadataCacheConfig {
            enabled: false,
            ..Default::default()
        };
        let cache = MetadataCache::new(config);
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", false),
        );
        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
    }

    #[test]
    fn ttl_expiry_returns_none_and_increments_evictions() {
        let config = MetadataCacheConfig {
            ttl_ms: 10,
            ..Default::default()
        };
        let cache = MetadataCache::new(config);
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k"),
            make_meta("k", false),
        );

        std::thread::sleep(Duration::from_millis(20));

        assert!(cache
            .get(&BucketId::new("b"), &ObjectKey::new("k"))
            .is_none());
        assert_eq!(cache.stats().evictions.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn per_bucket_isolation() {
        let cache = MetadataCache::new(MetadataCacheConfig::default());
        cache.put(
            BucketId::new("b1"),
            ObjectKey::new("k"),
            make_meta("k-b1", false),
        );
        cache.put(
            BucketId::new("b2"),
            ObjectKey::new("k"),
            make_meta("k-b2", false),
        );

        let got1 = cache
            .get(&BucketId::new("b1"), &ObjectKey::new("k"))
            .unwrap();
        let got2 = cache
            .get(&BucketId::new("b2"), &ObjectKey::new("k"))
            .unwrap();
        assert_eq!(got1.object_key.as_str(), "k-b1");
        assert_eq!(got2.object_key.as_str(), "k-b2");
    }

    #[test]
    fn lru_eviction_when_cache_full() {
        let config = MetadataCacheConfig {
            max_size_bytes: 1, // Very small — effectively 0 entries.
            ttl_ms: 0,
            enabled: true,
        };
        let cache = MetadataCache::new(config);

        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k1"),
            make_meta("k1", false),
        );
        cache.put(
            BucketId::new("b"),
            ObjectKey::new("k2"),
            make_meta("k2", false),
        );

        // At least one entry should have been evicted (max_size_bytes=1).
        let stats = cache.stats();
        assert!(
            stats.evictions.load(Ordering::Relaxed) > 0,
            "expected some evictions when max_size_bytes=1"
        );
    }
}

//! L3 Negative Cache — Bloom filter for non-existent keys.
//!
//! Answers "does this key exist?" without touching RocksDB. HEAD requests
//! for non-existent objects return 404 in constant time. Per-bucket Bloom
//! filters with configurable false-positive rates.

use std::{
    collections::hash_map::DefaultHasher,
    hash::{Hash, Hasher},
    sync::{
        atomic::{AtomicU64, AtomicUsize, Ordering},
        Arc,
    },
};

use dashmap::DashMap;
use oceanfs_core::{BucketId, MetadataStore, ObjectKey};
use parking_lot::RwLock;

/// Configuration for the negative cache.
#[derive(Debug, Clone)]
pub struct NegativeCacheConfig {
    /// Whether the cache is enabled.
    pub enabled: bool,
    /// Approximate size of each bucket's Bloom filter in bytes.
    pub size_bytes: u64,
    /// Target false-positive rate (e.g., 0.0001 = 0.01%).
    pub fp_rate: f64,
    /// Interval between automatic rebuilds in seconds (0 = no auto-rebuild).
    pub rebuild_interval_sec: u64,
}

impl Default for NegativeCacheConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            size_bytes: 64 * 1024 * 1024,
            fp_rate: 0.0001,
            rebuild_interval_sec: 3600,
        }
    }
}

/// Statistics for the negative cache.
#[derive(Debug, Default)]
pub struct NegativeCacheStats {
    /// Correctly predicted missing keys (filter said "definitely absent").
    pub hits: AtomicU64,
    /// False positives (filter said "maybe present" but key was absent).
    pub false_positives: AtomicU64,
    /// Number of rebuilds performed.
    pub rebuilds: AtomicU64,
    /// Current number of entries across all bucket filters.
    pub entry_count: AtomicUsize,
}

/// A Bloom filter with configurable false-positive rate.
///
/// Uses double hashing (Kirsch-Mitzenmacher scheme) to derive multiple
/// hash functions from two base hashes.
struct BloomFilter {
    /// Bit array stored as bytes.
    bits: Vec<u8>,
    /// Number of hash functions to use.
    hash_count: usize,
    /// Number of bits in the filter.
    bit_count: usize,
}

impl BloomFilter {
    /// Creates a new Bloom filter with the given size and target false-positive rate.
    ///
    /// The number of hash functions is chosen to minimize the false-positive rate
    /// for the given filter size.
    fn new(size_bytes: u64, fp_rate: f64) -> Self {
        let bit_count = (size_bytes as usize) * 8;
        let byte_count = bit_count / 8;
        // Optimal number of hash functions: k = -log2(fp_rate)
        let hash_count = Self::optimal_hash_count(fp_rate);
        Self {
            bits: vec![0u8; byte_count],
            hash_count,
            bit_count,
        }
    }

    /// Computes the optimal number of hash functions for a target FP rate.
    fn optimal_hash_count(fp_rate: f64) -> usize {
        if fp_rate <= 0.0 {
            return 1;
        }
        // k = -log2(p) = -ln(p) / ln(2)
        let k = (-fp_rate.ln() / std::f64::consts::LN_2).ceil() as usize;
        k.clamp(1, 16)
    }

    /// Returns `true` if the key MAY be present (possible false positive).
    fn contains(&self, bucket: &BucketId, key: &ObjectKey) -> bool {
        let (h1, h2) = hash_key(bucket, key);
        for i in 0..self.hash_count {
            let idx = hash_index(h1, h2, i, self.bit_count);
            let byte = self.bits[idx / 8];
            if (byte >> (idx % 8)) & 1 == 0 {
                return false;
            }
        }
        true
    }

    /// Inserts a key into the filter.
    fn insert(&mut self, bucket: &BucketId, key: &ObjectKey) {
        let (h1, h2) = hash_key(bucket, key);
        for i in 0..self.hash_count {
            let idx = hash_index(h1, h2, i, self.bit_count);
            self.bits[idx / 8] |= 1 << (idx % 8);
        }
    }
}

/// Per-bucket negative cache with its own Bloom filter.
struct BucketNegativeCache {
    filter: RwLock<BloomFilter>,
}

impl BucketNegativeCache {
    fn new(config: &NegativeCacheConfig) -> Self {
        Self {
            filter: RwLock::new(BloomFilter::new(config.size_bytes, config.fp_rate)),
        }
    }
}

/// L3 Negative Cache — per-bucket Bloom filters for non-existent keys.
///
/// # Examples
///
/// ```
/// use oceanfs_cache::NegativeCache;
/// use oceanfs_cache::NegativeCacheConfig;
/// use oceanfs_core::{BucketId, ObjectKey};
///
/// let cache = NegativeCache::new(NegativeCacheConfig::default());
/// cache.insert(&BucketId::new("b"), &ObjectKey::new("k"));
/// assert!(cache.contains(&BucketId::new("b"), &ObjectKey::new("k")));
/// ```
pub struct NegativeCache {
    config: NegativeCacheConfig,
    buckets: DashMap<BucketId, Arc<BucketNegativeCache>>,
    stats: NegativeCacheStats,
}

impl NegativeCache {
    /// Creates a new negative cache with the given configuration.
    pub fn new(config: NegativeCacheConfig) -> Self {
        Self {
            config,
            buckets: DashMap::new(),
            stats: NegativeCacheStats::default(),
        }
    }

    /// Returns `true` if the key MAY exist (possible false positive).
    /// Returns `false` if the key DEFINITELY does not exist.
    pub fn contains(&self, bucket: &BucketId, key: &ObjectKey) -> bool {
        if !self.config.enabled {
            // When disabled, always say "maybe" to force a real lookup.
            return true;
        }

        // Get or create the bucket filter (empty filter = all keys definitely absent).
        let bucket_cache = self
            .buckets
            .entry(bucket.clone())
            .or_insert_with(|| Arc::new(BucketNegativeCache::new(&self.config)))
            .clone();

        let result = bucket_cache.filter.read().contains(bucket, key);
        if !result {
            // Definitely absent — record as a hit for the negative cache.
            self.stats.hits.fetch_add(1, Ordering::Relaxed);
        }
        result
    }

    /// Inserts a key into the filter.
    pub fn insert(&self, bucket: &BucketId, key: &ObjectKey) {
        if !self.config.enabled {
            return;
        }

        let bucket_cache = self
            .buckets
            .entry(bucket.clone())
            .or_insert_with(|| Arc::new(BucketNegativeCache::new(&self.config)))
            .clone();

        bucket_cache.filter.write().insert(bucket, key);
        self.stats.entry_count.fetch_add(1, Ordering::Relaxed);
    }

    /// Rebuilds the bucket's Bloom filter from the metadata store.
    ///
    /// Scans all keys in the bucket and populates a fresh filter, then
    /// atomically swaps it with the old filter. Readers see a consistent
    /// view during the rebuild.
    ///
    /// # Errors
    ///
    /// Returns an error if the metadata store is unavailable.
    pub async fn rebuild(
        &self,
        metadata: Arc<dyn MetadataStore>,
    ) -> crate::Result<()> {
        // Rebuild all known buckets.
        for bucket_entry in self.buckets.iter() {
            let bucket = bucket_entry.key().clone();
            let bucket_cache = bucket_entry.value().clone();

            let keys = metadata
                .list_object_keys(&bucket)
                .map_err(crate::Error::RebuildIo)?;

            let mut new_filter = BloomFilter::new(self.config.size_bytes, self.config.fp_rate);

            for (_b, k) in &keys {
                new_filter.insert(&bucket, k);
            }

            {
                let mut old = bucket_cache.filter.write();
                *old = new_filter;
            }
        }

        self.stats.rebuilds.fetch_add(1, Ordering::Relaxed);
        Ok(())
    }

    /// Records a false positive: the filter said "maybe" but the key was absent.
    pub fn record_false_positive(&self) {
        self.stats.false_positives.fetch_add(1, Ordering::Relaxed);
    }

    /// Returns cache statistics.
    pub fn stats(&self) -> &NegativeCacheStats {
        &self.stats
    }
}

/// Compute two independent hash values for a bucket+key pair.
fn hash_key(bucket: &BucketId, key: &ObjectKey) -> (u64, u64) {
    let mut h1 = DefaultHasher::new();
    bucket.as_str().hash(&mut h1);
    key.as_str().hash(&mut h1);
    let hash1 = h1.finish();

    let mut h2 = DefaultHasher::new();
    h2.write_u64(hash1);
    h2.write_u8(0xAB); // Mix in a constant to decorrelate.
    let hash2 = h2.finish();

    (hash1, hash2)
}

/// Derives the i-th hash index from two base hashes (Kirsch-Mitzenmacher).
fn hash_index(h1: u64, h2: u64, i: usize, bit_count: usize) -> usize {
    let combined = h1.wrapping_add((i as u64).wrapping_mul(h2));
    (combined as usize) % bit_count
}

