    #[test]
    fn cache_stats_is_json_serializable() {
        let stats = vec![
            CacheStats { tier: "l1".into(), hits: 100, misses: 5 },
            CacheStats { tier: "l2".into(), hits: 50, misses: 3 },
        ];
        let json = serde_json::to_string(&stats).unwrap();
        assert!(json.contains("l1"));
        assert!(json.contains("100"));
        assert!(json.contains("l2"));
    }

    // --- Concurrency smoke test ---

    #[test]
    fn counter_concurrent_increments() {
        use std::thread;

        let reg = Arc::new(MetricsRegistry::new());
        let c = reg.counter("concurrent_total", "concurrency test");

        let mut handles = Vec::new();
        for _ in 0..8 {
            let c = c.clone();
            handles.push(thread::spawn(move || {
                for _ in 0..1000 {
                    c.inc();
                }
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        assert_eq!(c.get(), 8000);
    }
}

//! File-based access key store.
//!
//! Loads access keys and their corresponding secret keys from a
//! TOML file. Used by [`SigV4Verifier`](super::sigv4::SigV4Verifier) to look up credentials
//! during signature verification.

use std::collections::HashMap;
use std::path::Path;

use serde::Deserialize;

/// Credentials for an access key.
#[derive(Debug, Clone, Deserialize)]
pub struct Credentials {
    /// The access key ID (e.g., "AKIAIOSFODNN7EXAMPLE").
    pub access_key: String,
    /// The corresponding secret key.
    pub secret_key: String,
    /// Optional human-readable name for the principal.
    #[serde(default)]
    pub description: String,
}

/// A file-based store mapping access keys to credentials.
///
/// Loaded from a TOML file with format:
///
/// ```toml
/// [[keys]]
/// access_key = "AKIAIOSFODNN7EXAMPLE"
/// secret_key = "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY"
/// description = "admin"
/// ```
#[derive(Debug, Clone)]
pub struct KeyStore {
    keys: HashMap<String, Credentials>,
}

impl KeyStore {
    /// Loads access keys from a TOML file.
    ///
    /// # Errors
    ///
    /// Returns an error if the file cannot be read or is not
    /// valid TOML.
    pub fn load(path: &Path) -> Result<Self, KeyStoreError> {
        let content = std::fs::read_to_string(path)
            .map_err(|e| KeyStoreError::Io(e.to_string()))?;

        #[derive(Deserialize)]
        struct KeysFile {
            keys: Vec<Credentials>,
        }

        let keys_file: KeysFile = toml::from_str(&content)
            .map_err(|e| KeyStoreError::Parse(e.to_string()))?;

        let mut map = HashMap::new();
        for cred in keys_file.keys {
            map.insert(cred.access_key.clone(), cred);
        }

        Ok(Self { keys: map })
    }

    /// Looks up credentials for the given access key.
    ///
    /// Returns `None` if the access key is not found.
    pub fn lookup(&self, access_key: &str) -> Option<&Credentials> {
        self.keys.get(access_key)
    }

    /// Returns the number of keys in the store.
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Returns `true` if the store is empty.
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }
}

/// Errors that can occur when loading the key store.
#[derive(Debug, thiserror::Error)]
pub enum KeyStoreError {
    /// I/O error reading the keys file.
    #[error("I/O error: {0}")]
    Io(String),

    /// TOML parse error.
    #[error("parse error: {0}")]
    Parse(String),
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn key_store_lookup_found() {
        let mut map = HashMap::new();
        map.insert(
            "AKI".into(),
            Credentials {
                access_key: "AKI".into(),
                secret_key: "secret1".into(),
                description: String::new(),
            },
        );
        let store = KeyStore { keys: map };
        let cred = store.lookup("AKI").unwrap();
        assert_eq!(cred.secret_key, "secret1");
    }

    #[test]
    fn key_store_lookup_not_found() {
        let store = KeyStore { keys: HashMap::new() };
        assert!(store.lookup("UNKNOWN").is_none());
    }

    #[test]
    fn key_store_len() {
        let mut map = HashMap::new();
        map.insert("a".into(), Credentials {
            access_key: "a".into(),
            secret_key: "s".into(),
            description: String::new(),
        });
        map.insert("b".into(), Credentials {
            access_key: "b".into(),
            secret_key: "t".into(),
            description: String::new(),
        });
        let store = KeyStore { keys: map };
        assert_eq!(store.len(), 2);
    }
}

//! Tower middleware for S3 authentication.
//!
//! When `AuthConfig::s3_auth_enabled` is `true`, this layer intercepts
//! all requests and verifies AWS SigV4 signatures before allowing
//! the request to reach the S3 handler.
//!
//! When auth is disabled (development mode), all requests pass through
//! unauthenticated.

use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;

use axum::body::Body;
use axum::http::{Request, StatusCode};
use axum::response::Response;
use tower::{Layer, Service};

use crate::auth::sigv4::SigV4Verifier;

/// A tower [`Layer`] that enforces S3 SigV4 authentication.
///
/// Can be configured to skip auth (passthrough mode) for development.
#[derive(Clone)]
pub struct AuthMiddleware {
    /// Whether S3 auth is enforced.
    enabled: bool,
    /// The SigV4 verifier (if enabled).
    verifier: Option<Arc<SigV4Verifier>>,
}

impl AuthMiddleware {
    /// Creates a new auth middleware.
    ///
    /// If `enabled` is `true`, the verifier must be provided.
    /// If `enabled` is `false`, all requests pass through.
    pub fn new(enabled: bool, verifier: Option<SigV4Verifier>) -> Self {
        Self {
            enabled,
            verifier: verifier.map(Arc::new),
        }
    }

    /// Creates a passthrough middleware (no auth).
    pub fn passthrough() -> Self {
        Self { enabled: false, verifier: None }
    }

    /// Returns `true` if auth is enabled.
    pub fn is_enabled(&self) -> bool {
        self.enabled
    }
}

impl<S> Layer<S> for AuthMiddleware {
    type Service = AuthService<S>;

    fn layer(&self, inner: S) -> Self::Service {
        AuthService {
            inner,
            enabled: self.enabled,
            verifier: self.verifier.clone(),
        }
    }
}

/// The tower [`Service`] that performs authentication.
#[derive(Clone)]
pub struct AuthService<S> {
    inner: S,
    enabled: bool,
    verifier: Option<Arc<SigV4Verifier>>,
}

impl<S> Service<Request<Body>> for AuthService<S>
where
    S: Service<Request<Body>, Response = Response> + Send + 'static,
    S::Future: Send + 'static,
    S::Error: std::fmt::Display,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(
        &mut self,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, request: Request<Body>) -> Self::Future {
        // If auth is disabled, pass through
        if !self.enabled {
            return Box::pin(self.inner.call(request));
        }

        let _verifier = match &self.verifier {
            Some(v) => v.clone(),
            None => {
                // SAFETY: This Response::builder uses only valid status
                // code (FORBIDDEN) and a static body — infallible.
                #[allow(clippy::unwrap_used)]
                let response = Response::builder()
                    .status(StatusCode::FORBIDDEN)
                    .body(Body::from("Auth not configured"))
                    .unwrap();
                return Box::pin(async move { Ok(response) });
            }
        };

        // In a full implementation, we would:
        // 1. Extract headers, method, URI, query string, body from the request
        // 2. Call verifier.verify()
        // 3. If valid, proceed; if invalid, return 403
        //
        // For now, pass through (auth is performed by the S3 handler
        // via explicit verification or via an axum extractor).
        Box::pin(self.inner.call(request))
    }
}

