#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn auth_middleware_passthrough_is_disabled() {
        let mw = AuthMiddleware::passthrough();
        assert!(!mw.is_enabled());
    }

    #[test]
    fn auth_middleware_enabled_when_configured() {
        let mw = AuthMiddleware::new(true, None);
        assert!(mw.is_enabled());
    }
