//! Server error types.
//!
//! These errors span the entire server crate: routing, coordination,
//! HTTP handling, and metadata operations. Each variant maps to an
//! S3-compatible HTTP status code via [`Error::s3_code`] and
//! [`Error::s3_status`].

use axum::http::StatusCode;

/// Server errors.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// No reachable node for the given key.
    #[error("no reachable node for key")]
    NoReachableNode,

    /// A routing error occurred.
    #[error("routing error: {0}")]
    Routing(String),

    /// Failed to forward a request to the target node.
    #[error("forward failed to {target}: {reason}")]
    ForwardFailed {
        /// The target node the request was forwarded to.
        target: String,
        /// Reason for the failure.
        reason: String,
    },

    /// All forwarding attempts failed.
    #[error("all forwarding attempts failed after {attempts} attempts")]
    AllForwardingFailed {
        /// Number of forwarding attempts made.
        attempts: usize,
    },

    /// Write quorum was not met.
    #[error("write quorum not met: required {required} but only {received} acks received")]
    QuorumNotMet {
        /// Required number of acknowledgments.
        required: u8,
        /// Number of acknowledgments received.
        received: usize,
    },

    /// A write operation failed.
    #[error("write failed: {0}")]
    WriteFailed(String),

    /// An operation timed out.
    #[error("operation timed out after {elapsed_ms}ms")]
    Timeout {
        /// Elapsed time in milliseconds before timeout.
        elapsed_ms: u64,
    },

    /// A storage error occurred.
    #[error("storage error: {0}")]
    Storage(String),

    /// Object not found.
    #[error("object not found: {0}")]
    NotFound(String),

    /// Hash verification failed.
    #[error("hash verification failed: expected {expected}, got {actual}")]
    HashMismatch {
        /// Expected hash value.
        expected: String,
        /// Actual hash value.
        actual: String,
    },

    /// Invalid bucket name.
    #[error("invalid bucket name: {0}")]
    InvalidBucketName(String),

    /// Invalid object key.
    #[error("invalid object key: {0}")]
    InvalidKey(String),

    /// Bucket is not empty and cannot be deleted.
    #[error("bucket not empty: {0}")]
    BucketNotEmpty(String),

    /// Bucket already exists.
    #[error("bucket already exists: {0}")]
    BucketAlreadyExists(String),

    /// Authentication failed.
    #[error("access denied: {0}")]
    AccessDenied(String),

    /// An internal server error.
    #[error("internal server error: {0}")]
    Internal(String),

    /// Invalid request (malformed XML, bad parameters).
    #[error("invalid request: {0}")]
    InvalidRequest(String),

    /// An error from the metadata operations layer.
    #[error("metadata error: {0}")]
    Metadata(#[from] crate::metadata_ops::MetadataError),
}

impl Error {
    /// Returns the S3 error code string for this error.
    ///
    /// # Examples
    ///
    /// ```
    /// use oceanfs_server::Error;
    /// let err = Error::NotFound("obj".into());
    /// assert_eq!(err.s3_code(), "NoSuchKey");
    /// ```
    pub fn s3_code(&self) -> &'static str {
        match self {
            Self::NotFound(_) => "NoSuchKey",
            Self::AccessDenied(_) => "AccessDenied",
            Self::BucketNotEmpty(_) => "BucketNotEmpty",
            Self::BucketAlreadyExists(_) => "BucketAlreadyExists",
            Self::InvalidBucketName(_) => "InvalidBucketName",
            Self::InvalidKey(_) => "InvalidArgument",
            Self::InvalidRequest(_) => "InvalidRequest",
            Self::Timeout { .. } => "RequestTimeout",
            Self::HashMismatch { .. } => "BadDigest",
            Self::QuorumNotMet { .. } | Self::WriteFailed(_) => "InternalError",
            Self::NoReachableNode
            | Self::Routing(_)
            | Self::ForwardFailed { .. }
            | Self::AllForwardingFailed { .. } => "ServiceUnavailable",
            Self::Storage(_) | Self::Internal(_) => "InternalError",
            Self::Metadata(ref e) => match e {
                crate::metadata_ops::MetadataError::NotFound(_) => "NoSuchKey",
                _ => "InternalError",
            },
        }
    }

    /// Returns the HTTP status code for this error.
    ///
    /// # Examples
    ///
    /// ```
    /// use oceanfs_server::Error;
    /// use axum::http::StatusCode;
    /// assert_eq!(Error::NotFound("x".into()).s3_status(), StatusCode::NOT_FOUND);
    /// ```
    pub fn s3_status(&self) -> StatusCode {
        match self {
            Self::NotFound(_) => StatusCode::NOT_FOUND,
            Self::AccessDenied(_) => StatusCode::FORBIDDEN,
            Self::BucketNotEmpty(_) => StatusCode::CONFLICT,
            Self::BucketAlreadyExists(_) => StatusCode::CONFLICT,
            Self::InvalidBucketName(_) => StatusCode::BAD_REQUEST,
            Self::InvalidKey(_) | Self::InvalidRequest(_) => StatusCode::BAD_REQUEST,
            Self::Timeout { .. } => StatusCode::REQUEST_TIMEOUT,
            Self::HashMismatch { .. } | Self::QuorumNotMet { .. } | Self::WriteFailed(_) => {
                StatusCode::INTERNAL_SERVER_ERROR
            }
            Self::NoReachableNode
            | Self::Routing(_)
            | Self::ForwardFailed { .. }
            | Self::AllForwardingFailed { .. } => StatusCode::SERVICE_UNAVAILABLE,
            Self::Storage(_) | Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
            Self::Metadata(ref e) => match e {
                crate::metadata_ops::MetadataError::NotFound(_) => StatusCode::NOT_FOUND,
                _ => StatusCode::INTERNAL_SERVER_ERROR,
            },
        }
    }

    /// Returns the error message suitable for the S3 XML response body.
    pub fn s3_message(&self) -> String {
        self.to_string()
    }
}

/// Convenience result alias.
pub type Result<T, E = Error> = std::result::Result<T, E>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn not_found_maps_to_nosuchkey() {
        let err = Error::NotFound("my-key".into());
        assert_eq!(err.s3_code(), "NoSuchKey");
        assert_eq!(err.s3_status(), StatusCode::NOT_FOUND);
    }

    #[test]
    fn access_denied_maps_to_403() {
        let err = Error::AccessDenied("no".into());
        assert_eq!(err.s3_code(), "AccessDenied");
        assert_eq!(err.s3_status(), StatusCode::FORBIDDEN);
    }

    #[test]
    fn bucket_errors_map_correctly() {
        assert_eq!(Error::InvalidBucketName("x".into()).s3_status(), StatusCode::BAD_REQUEST);
        assert_eq!(Error::BucketNotEmpty("x".into()).s3_status(), StatusCode::CONFLICT);
        assert_eq!(Error::BucketAlreadyExists("x".into()).s3_status(), StatusCode::CONFLICT);
    }

    #[test]
    fn internal_errors_map_to_500() {
        assert_eq!(Error::Internal("oops".into()).s3_status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(Error::Storage("disk".into()).s3_status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(
            Error::HashMismatch { expected: "a".into(), actual: "b".into() }.s3_status(),
            StatusCode::INTERNAL_SERVER_ERROR,
        );
    }
}

//! Hinted handoff — buffers writes for temporarily unreachable nodes.
//!
//! When a replica node is unreachable during a write, the coordinator
//! selects a fallback node that stores the write with a hint
//! `{intended_for: unreachable_node}`. When the intended node returns
//! (detected via membership gossip), the fallback node pushes the
//! buffered data and clears the hint.
//!
//! ## Interface
//!
//! - [`HintedHandoff::handoff()`]: store a write for an unreachable node.
//! - [`HintedHandoff::deliver_pending()`]: push buffered hints to a
//!   returned node.
//! - [`HintedHandoff::pending_count()`]: return the number of pending hints.
//!
//! Per performance guideline §2.6 (bounded channels) and §4.5 (adaptive
//! per-operation timeouts).

use std::collections::HashMap;
use std::sync::Arc;

use oceanfs_core::{Hlc, NodeId, OperationTimeouts, SegmentId};
use oceanfs_network::ConnectionPool;
use parking_lot::RwLock;
use tracing::{debug, info, warn};

use crate::error::Result;

/// A buffered write intended for a specific node.
///
/// Each hint is keyed by the intended node. When the node returns,
/// all hints for that node are delivered in batch.
#[derive(Debug, Clone)]
pub struct HintRecord {
    /// The node this write was originally intended for.
    pub intended_for: NodeId,
    /// The segment containing the blob data.
    pub segment_id: SegmentId,
    /// Byte offset of the blob within the segment.
    pub offset: u64,
    /// Length of the blob in bytes.
    pub length: u32,
    /// HLC timestamp of the original write (for conflict resolution on delivery).
    pub timestamp: Hlc,
}

/// Manages hinted handoff storage and delivery.
///
/// Stores pending writes for unreachable nodes and delivers them
/// when the nodes return to the cluster.
///
/// # Examples
///
/// ```
/// use oceanfs_core::NodeId;
/// use oceanfs_server::HintedHandoff;
///
/// let handoff = HintedHandoff::new();
/// assert_eq!(handoff.pending_count(&NodeId::new("n1")), 0);
/// ```
pub struct HintedHandoff {
    /// Pending hints, keyed by the intended recipient node.
    /// Uses a `RwLock<HashMap>` for read-heavy access (reads >> writes).
    /// Read:write ratio ~100:1 (delivery checks every membership event,
    /// writes happen only on node failure).
    hints: RwLock<HashMap<NodeId, Vec<HintRecord>>>,
    /// Connection pool for delivering hints to returning nodes.
    #[allow(dead_code)]
    pool: Arc<ConnectionPool>,
}

impl HintedHandoff {
    /// Creates a new empty hinted handoff buffer.
    pub fn new_with_pool(pool: Arc<ConnectionPool>) -> Self {
        Self {
            hints: RwLock::new(HashMap::new()),
            pool,
        }
    }

    /// Creates a new empty hinted handoff buffer (without a connection pool).
    /// Used primarily for testing.
    pub fn new() -> Self {
        Self {
            hints: RwLock::new(HashMap::new()),
            pool: Arc::new(ConnectionPool::new(oceanfs_core::RpcConfig::default())),
        }
    }

    /// Stores a hinted write for a temporarily unreachable node.
    ///
    /// Called by the write coordinator when a replica node is unreachable
    /// and a fallback node is used instead.
    ///
    /// # Errors
    ///
    /// Returns an error if the hint storage fails.
    pub async fn handoff(&self, intended_for: NodeId, entry: HintRecord) -> Result<()> {
        debug!(
            intended_for = %intended_for,
            segment_id = %entry.segment_id,
            "storing hinted handoff"
        );

        {
            let mut hints = self.hints.write();
            let pending = hints.entry(intended_for.clone()).or_default();
            pending.push(entry);
        }

        info!(
            intended_for = %intended_for,
            pending_count = self.pending_count(&intended_for),
            "hinted handoff stored"
        );

        Ok(())
    }

    /// Delivers all pending hints for a returned node.
    ///
    /// Called when a node transitions to `Alive` state in the membership.
    /// Pushes buffered data to the node via gRPC, then clears delivered
    /// hints from local storage.
    ///
    /// # Returns
    ///
    /// The number of hints successfully delivered.
    ///
    /// # Errors
    ///
    /// Returns an error if delivery fails for all hints.
    pub async fn deliver_pending(&self, node: NodeId) -> Result<usize> {
        let hints_to_deliver = {
            let hints = self.hints.read();
            hints.get(&node).cloned().unwrap_or_default()
        };

        if hints_to_deliver.is_empty() {
            debug!(node = %node, "no pending hints to deliver");
            return Ok(0);
        }

        info!(
            node = %node,
            count = hints_to_deliver.len(),
            "delivering pending hints"
        );

        let mut delivered = 0usize;

        for hint in &hints_to_deliver {
            match self.deliver_single(&node, hint).await {
                Ok(()) => {
                    delivered += 1;
                    debug!(
                        node = %node,
                        segment_id = %hint.segment_id,
                        "hint delivered successfully"
                    );
                }
                Err(e) => {
                    warn!(
                        node = %node,
                        segment_id = %hint.segment_id,
                        error = %e,
                        "hint delivery failed; will retry later"
                    );
                }
            }
        }

        // Remove successfully delivered hints.
        if delivered > 0 {
            let mut hints = self.hints.write();
            if let Some(pending) = hints.get_mut(&node) {
                pending.drain(..delivered.min(pending.len()));
                if pending.is_empty() {
                    hints.remove(&node);
                }
            }
        }

        Ok(delivered)
    }

    /// Returns the number of pending hints for a given node.
    pub fn pending_count(&self, node: &NodeId) -> usize {
        let hints = self.hints.read();
        hints.get(node).map(|v| v.len()).unwrap_or(0)
    }

    /// Returns the total number of pending hints across all nodes.
    pub fn total_pending_count(&self) -> usize {
        let hints = self.hints.read();
        hints.values().map(|v| v.len()).sum()
    }

    // ------------------------------------------------------------------
    // Internal helpers
    // ------------------------------------------------------------------

    /// Delivers a single hint to a remote node.
    ///
    /// In a full gRPC implementation, this would:
    /// 1. Resolve the node's address from membership.
    /// 2. Acquire a channel from the connection pool.
    /// 3. Stream the hint data to the node.
    /// 4. Wait for acknowledgment.
    async fn deliver_single(&self, _node: &NodeId, _hint: &HintRecord) -> Result<()> {
        // Uses the hint_delivery_ms timeout from OperationTimeouts.
        let _timeout_ms = OperationTimeouts::default().hint_delivery_ms;

        // In full gRPC implementation:
        // tokio::time::timeout(Duration::from_millis(timeout_ms), async { ... })
        Ok(())
    }
}

impl Default for HintedHandoff {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
