        )
        .await
        .unwrap();

        hh.handoff(
            node_a.clone(),
            HintRecord {
                intended_for: node_a.clone(),
                segment_id: SegmentId::new(),
                offset: 50,
                length: 50,
                timestamp: Hlc::zero(),
            },
        )
        .await
        .unwrap();

        hh.handoff(
            node_b.clone(),
            HintRecord {
                intended_for: node_b.clone(),
                segment_id: SegmentId::new(),
                offset: 0,
                length: 200,
                timestamp: Hlc::zero(),
            },
        )
        .await
        .unwrap();

        assert_eq!(hh.pending_count(&node_a), 2);
        assert_eq!(hh.pending_count(&node_b), 1);
        assert_eq!(hh.total_pending_count(), 3);
    }

    #[tokio::test]
    async fn deliver_pending_clears_hints() {
        let hh = HintedHandoff::new();
        let node = NodeId::new("n1");

        hh.handoff(
            node.clone(),
            HintRecord {
                intended_for: node.clone(),
                segment_id: SegmentId::new(),
                offset: 0,
                length: 100,
                timestamp: Hlc::zero(),
            },
        )
        .await
        .unwrap();

        let delivered = hh.deliver_pending(node.clone()).await.unwrap();
        // In the test harness, deliver_single always succeeds.
        assert_eq!(delivered, 1);
        assert_eq!(hh.pending_count(&node), 0);
    }

    #[tokio::test]
    async fn deliver_pending_no_hints_returns_zero() {
        let hh = HintedHandoff::new();
        let delivered = hh.deliver_pending(NodeId::new("unknown")).await.unwrap();
        assert_eq!(delivered, 0);
    }

    #[tokio::test]
    async fn pending_count_accurate_after_handoff() {
        let hh = HintedHandoff::new();
        let node = NodeId::new("target");

        assert_eq!(hh.pending_count(&node), 0);

        hh.handoff(
            node.clone(),
            HintRecord {
                intended_for: node.clone(),
                segment_id: SegmentId::new(),
                offset: 0,
                length: 42,
                timestamp: Hlc::zero(),
            },
        )
        .await
        .unwrap();

        assert_eq!(hh.pending_count(&node), 1);
    }
}

//! S3-compatible HTTP server and request coordinators.
//!
//! This crate provides the HTTP server layer (S3-compatible REST API),
//! distributed read/write coordinators, and the integration glue
//! between the storage, routing, membership, and networking crates.
//!
//! ## Architecture
