//! Request router — integrates ring, membership, and connection pool
//! to dispatch blob operations to the correct replica set.

use std::sync::Arc;

use oceanfs_core::{HashKey, NodeId, OperationType};
use oceanfs_membership::Membership;
use oceanfs_network::ConnectionPool;
use oceanfs_routing::RingCache;
use tracing::{debug, warn};

use crate::error::{Error, Result};

/// A request to be routed to the correct replica set.
#[derive(Debug, Clone)]
pub struct RouteRequest {
    /// Pre-computed key hash.
    pub key: HashKey,
    /// The bucket identifier.
    pub bucket: oceanfs_core::BucketId,
    /// The operation type.
    pub operation: OperationType,
}

/// The result of a routing decision.
#[derive(Debug, Clone)]
pub struct RouteResponse {
    /// Whether this node is part of the replica set.
    pub is_local: bool,
    /// The ordered list of successor nodes for this key.
    pub replica_set: Vec<NodeId>,
    /// The node to forward the request to (if not local).
    pub forward_target: Option<NodeId>,
}

/// Routes requests to the correct replica set.
///
/// Integrates the ring cache for consistent-hashing lookups,
/// membership for up-to-date node addresses, and the connection
/// pool for forwarding requests to remote nodes.
///
/// # Examples
///
/// ```ignore
/// use std::sync::Arc;
/// use oceanfs_core::{HashKey, ObjectKey, OperationType};
/// use oceanfs_routing::hash_key;
/// use oceanfs_server::Router;
///
/// # async fn example(router: &Router) {
/// let key = ObjectKey::new("photos/cat.jpg");
/// let hash_key = HashKey::from_bytes(hash_key(key.as_str().as_bytes()));
/// let response = router.route(hash_key).await.unwrap();
/// if response.is_local {
///     // process locally
/// } else {
///     // forward to response.forward_target
/// }
/// # }
/// ```
pub struct Router {
    ring: Arc<RingCache>,
    membership: Arc<Membership>,
    pool: Arc<ConnectionPool>,
    /// This node's identifier.
    node_id: NodeId,
}

impl Router {
    /// Creates a new router.
    pub fn new(
        ring: Arc<RingCache>,
        membership: Arc<Membership>,
        pool: Arc<ConnectionPool>,
        node_id: NodeId,
    ) -> Self {
        Self { ring, membership, pool, node_id }
    }

    /// Routes a request by key hash.
    ///
    /// Determines the replica set from the ring and checks whether
    /// this node is in the replica set. If not, the first successor
    /// is returned as the forward target.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Routing`] if the ring is empty and no
    /// replica set can be determined.
    pub async fn route(&self, key: HashKey) -> Result<RouteResponse> {
        let replica_set = self.ring.lookup(key.as_bytes());

        if replica_set.is_empty() {
            return Err(Error::Routing("ring returned empty replica set".into()));
        }

        let is_local = replica_set.contains(&self.node_id);

        let forward_target = if is_local {
            None
        } else {
            replica_set.first().cloned()
        };

        debug!(
            is_local = is_local,
            replica_count = replica_set.len(),
            forward = ?forward_target,
            "routing decision"
        );

        Ok(RouteResponse { is_local, replica_set, forward_target })
    }

    /// Routes with forwarding retry on failure.
    ///
    /// Attempts to route to the first successor. If the forward fails,
    /// tries the next successor in the replica set, up to N attempts.
    ///
    /// Returns the response from the first successful forward, or an
    /// error if all attempts fail.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Routing`] if the ring is empty.
    /// Returns [`Error::AllForwardingFailed`] if all successors are
    /// unreachable.
    pub async fn route_with_retry(&self, key: HashKey) -> Result<RouteResponse> {
        let replica_set = self.ring.lookup(key.as_bytes());

        if replica_set.is_empty() {
            return Err(Error::Routing("ring returned empty replica set".into()));
        }

        // If this node is in the replica set, handle locally.
        if replica_set.contains(&self.node_id) {
            return Ok(RouteResponse {
                is_local: true,
                replica_set,
                forward_target: None,
            });
        }

        // Try each successor in order.
        let mut attempts = 0usize;
        for target in replica_set.clone() {
            attempts += 1;

            // Check if target is alive.
            if let Some(state) = self.membership.state_of(&target) {
                if !matches!(state, oceanfs_core::NodeState::Alive) {
                    debug!(target = %target, state = ?state, "skipping non-alive node");
                    continue;
                }
            }

            // Attempt to forward to the target.
            match self.try_forward(&target).await {
                Ok(()) => {
                    return Ok(RouteResponse {
                        is_local: false,
                        replica_set,
                        forward_target: Some(target),
                    });
                }
                Err(e) => {
                    warn!(target = %target, attempt = attempts, error = %e, "forward attempt failed");
                }
            }
        }

        Err(Error::AllForwardingFailed { attempts })
    }

    /// Attempts to forward a request to a specific target node.
    ///
    /// Acquires a gRPC channel from the pool and checks connectivity.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ForwardFailed`] if the target is not found in
    /// membership or the channel cannot be acquired.
    async fn try_forward(&self, target: &NodeId) -> Result<()> {
        // In a real implementation, this would resolve the target's
        // address from membership, acquire a channel from the pool,
        // and make the actual gRPC forwarding call.
        //
        // For now, we simply verify that the target exists in membership
        // and that we can acquire a channel.
        let _state = self
            .membership
            .state_of(target)
            .ok_or_else(|| Error::ForwardFailed {
                target: target.to_string(),
                reason: "node not found in membership".into(),
            })?;

        // Channel acquisition is deferred to the actual RPC call site.
        // The pool.get_channel(addr) call will be made by the gRPC
        // client stub when making the forwarded request.

        debug!(target = %target, "forward target validated");
        Ok(())
    }

    /// Returns a reference to the ring cache.
    pub fn ring(&self) -> &Arc<RingCache> {
        &self.ring
    }

    /// Returns a reference to the membership.
    pub fn membership(&self) -> &Arc<Membership> {
        &self.membership
    }

    /// Returns a reference to the connection pool.
    pub fn pool(&self) -> &Arc<ConnectionPool> {
        &self.pool
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use std::net::SocketAddr;

    use oceanfs_core::{GossipConfig, Incarnation, NodeId, NodeState, RingConfig, RpcConfig};
    use oceanfs_routing::{hash_key, Ring};

    use super::*;

    fn make_hash_key(s: &str) -> HashKey {
        HashKey::from_bytes(hash_key(s.as_bytes()))
    }

    fn make_router(local_node_id: &str, ring_nodes: &[&str]) -> Router {
        let mut ring = Ring::new(RingConfig { vnodes_per_node: 8, replication_factor: 3 });
        for node in ring_nodes {
            ring.add_node(NodeId::new(*node));
        }

        let ring_cache = Arc::new(RingCache::new(ring));
        let addr: SocketAddr = "127.0.0.1:9001".parse().unwrap();
        let membership = Arc::new(Membership::new(
            NodeId::new(local_node_id), addr, GossipConfig::default(), ring_cache.clone(),
        ));

        for node in ring_nodes {
            membership.upsert_node(NodeId::new(*node), NodeState::Alive, Incarnation::new(1), addr);
        }
        let pool = Arc::new(ConnectionPool::new(RpcConfig::default()));

        Router::new(ring_cache, membership, pool, NodeId::new(local_node_id))
    }

    #[test]
    fn hash_key_deterministic() {
        let k1 = make_hash_key("a");
        let k2 = make_hash_key("a");
        assert_eq!(k1.as_bytes(), k2.as_bytes());
    }

    #[test]
    fn hash_key_different_for_different_keys() {
        let k1 = make_hash_key("a");
        let k2 = make_hash_key("b");
        assert_ne!(k1.as_bytes(), k2.as_bytes());
    }

    #[test]
    fn route_with_cache_only_returns_replica_set() {
        let mut ring = Ring::new(RingConfig { vnodes_per_node: 16, replication_factor: 3 });
        ring.add_node(NodeId::new("a"));
        ring.add_node(NodeId::new("b"));
        ring.add_node(NodeId::new("c"));

        let cache = Arc::new(RingCache::new(ring));
        let key = make_hash_key("test");
        let replica_set = cache.lookup(key.as_bytes());
        assert!(!replica_set.is_empty());
        assert!(replica_set.len() <= 3);
    }

    #[tokio::test]
    async fn route_local_node_in_replica_set_is_local_true() {
        let router = make_router("node-a", &["node-a", "node-b", "node-c"]);
        let key = make_hash_key("test-key");

        let response = router.route(key).await.unwrap();
        assert!(response.is_local, "local node should be in its own replica set");
        assert!(response.forward_target.is_none(), "forward_target should be None when local");
    }

    #[tokio::test]
    async fn route_local_node_not_in_replica_set_has_forward_target() {
        let router = make_router("node-x", &["node-a", "node-b", "node-c"]);
        let key = make_hash_key("test-key");

        let response = router.route(key).await.unwrap();
        assert!(!response.is_local, "node-x should not be in the replica set");
        assert!(response.forward_target.is_some(), "forward_target should be set");
    }

    #[tokio::test]
    async fn route_with_retry_local_node_is_local_true() {
        let router = make_router("node-a", &["node-a", "node-b"]);
        let key = make_hash_key("test");

        let response = router.route_with_retry(key).await.unwrap();
        assert!(response.is_local);
        assert!(response.forward_target.is_none());
    }

    #[tokio::test]
    async fn route_with_retry_non_local_selects_first_alive() {
        // node-x is not in the ring, so all targets are remote.
        let router = make_router("node-x", &["node-a", "node-b", "node-c"]);
        let key = make_hash_key("test");

        let response = router.route_with_retry(key).await.unwrap();
        assert!(!response.is_local);
        // The first alive node in the replica set should be the forward target.
        assert!(response.forward_target.is_some());
    }

    #[tokio::test]
    async fn route_empty_ring_returns_error() {
        let ring = Ring::new(RingConfig { vnodes_per_node: 8, replication_factor: 3 });
        let ring_cache = Arc::new(RingCache::new(ring));
        let addr: SocketAddr = "127.0.0.1:9001".parse().unwrap();
        let membership = Arc::new(Membership::new(
            NodeId::new("n1"), addr, GossipConfig::default(), ring_cache.clone(),
        ));
        let pool = Arc::new(ConnectionPool::new(RpcConfig::default()));
        let router = Router::new(ring_cache, membership, pool, NodeId::new("n1"));

        let key = make_hash_key("test");
        let result = router.route(key).await;
        assert!(result.is_err(), "routing with empty ring should fail");
    }
}

//! S3-compatible HTTP handlers.
//!
//! Implements the standard S3 REST API operations (PUT, GET, HEAD,
//! DELETE, LIST) with S3-compatible XML responses and error formatting.
//!
//! ## Architecture
//!
//! The handler delegates to:
//! - [`WriteCoordinator`] for PUT (blob writes with quorum)
//! - [`ReadCoordinator`] for GET and HEAD (blob reads + metadata)
//! - [`MetadataOps`] for DELETE and LIST (tombstone + prefix scan)
//! - [`BucketConfigStore`] for bucket CRUD
//!
//! Per performance guideline §4.2 (HTTP/2), §4.3 (TCP_NODELAY),
//! and §13.2 (`anyhow` only at application boundary — we use
//! concrete [`Error`] types).

use std::collections::HashMap;
use std::sync::Arc;

use axum::{
    body::Body,
    extract::{Path, Query, State},
    http::{header, HeaderMap, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    Router,
};
use bytes::Bytes;
use oceanfs_core::{BucketId, HashKey, ObjectKey};
use oceanfs_routing::hash_key;
use tracing::{debug, error, info};

use crate::bucket_config::BucketConfigStore;
use crate::error::Error;
use crate::metadata_ops::MetadataOps;
use crate::read_coordinator::{ReadCoordinator, ReadRequest};
use crate::s3_xml;
use crate::write_coordinator::{WriteCoordinator, WriteRequest};

// ---------------------------------------------------------------------------
// Helper: safe HeaderValue construction
// ---------------------------------------------------------------------------

/// Builds a [`HeaderValue`] from a string, falling back to an
/// empty static value on failure.
fn header_val(s: &str) -> HeaderValue {
    HeaderValue::from_str(s).unwrap_or(HeaderValue::from_static(""))
}

// ---------------------------------------------------------------------------
// AppState
// ---------------------------------------------------------------------------

/// Shared application state for all S3 HTTP handlers.
///
/// Each field is wrapped in `Arc` so it can be shared across
/// concurrent connections without synchronization overhead.
#[derive(Clone)]
pub(crate) struct AppState {
    /// Write coordinator for PUT operations.
    pub write: Arc<WriteCoordinator>,
    /// Read coordinator for GET/HEAD operations.
    pub read: Arc<ReadCoordinator>,
    /// Metadata store for DELETE/LIST operations.
    pub metadata: Arc<dyn MetadataOps>,
    /// Bucket configuration store for bucket CRUD.
    pub buckets: Arc<BucketConfigStore>,
    /// MIME type map by file extension.
    pub mime_types: Arc<MimeMap>,
}

// ---------------------------------------------------------------------------
// S3Handler
// ---------------------------------------------------------------------------

/// S3 API HTTP handler.
///
/// Wraps an axum `Router` that serves the S3-compatible REST API.
/// Construct with [`S3Handler::new`] and mount with
/// [`S3Handler::into_router`].
///
/// # Examples
///
/// ```ignore
/// # use std::sync::Arc;
/// # use oceanfs_server::{S3Handler, WriteCoordinator, ReadCoordinator};
/// # use oceanfs_server::metadata_ops::MetadataOps;
/// # use oceanfs_server::bucket_config::BucketConfigStore;
/// # async fn example(
/// #     write: Arc<WriteCoordinator>,
/// #     read: Arc<ReadCoordinator>,
/// #     metadata: Arc<dyn MetadataOps>,
/// #     buckets: Arc<BucketConfigStore>,
/// # ) {
/// let handler = S3Handler::new(write, read, metadata, buckets);
/// let router = handler.into_router();
/// // Mount in an axum server: axum::serve(listener, router).await
/// # }
/// ```
pub struct S3Handler {
    state: AppState,
}

impl S3Handler {
    /// Creates a new S3 handler with the given dependencies.
    ///
    /// All dependencies are injected via `Arc` for testability and
    /// to support the composition-root pattern in `oceanfs-node`.
    pub fn new(
        write: Arc<WriteCoordinator>,
        read: Arc<ReadCoordinator>,
        metadata: Arc<dyn MetadataOps>,
        buckets: Arc<BucketConfigStore>,
    ) -> Self {
        let state = AppState {
            write,
            read,
            metadata,
            buckets,
            mime_types: Arc::new(MimeMap::default()),
        };
        Self { state }
    }

    /// Consumes the handler and returns an axum `Router`.
    ///
    /// The returned router can be mounted in an axum `Server` via
    /// `axum::serve(listener, router)`.
    pub fn into_router(self) -> Router {
        let state = self.state;

        Router::new()
            // Object operations: /{bucket}/{*key}
            .route(
                "/{bucket}/{*key}",
                axum::routing::put(put_object)
                    .get(get_object)
                    .head(head_object)
                    .delete(delete_object),
            )
            // Bucket operations: /{bucket}
            .route(
                "/{bucket}",
                axum::routing::put(create_bucket)
                    .get(list_objects)
                    .delete(delete_bucket),
            )
            .with_state(state)
    }
}

// ---------------------------------------------------------------------------
// Object handlers
// ---------------------------------------------------------------------------

/// PUT /{bucket}/{key} — create or overwrite an object.
///
/// Delegates to [`WriteCoordinator::put`] for blob storage with
/// quorum replication. Returns `200 OK` with the `ETag` header.
///
/// # Errors
///
/// Returns S3-compatible XML error responses for all failure modes.
async fn put_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
    body: Bytes,
) -> Response {
    let bucket_id = BucketId::new(&bucket);
    let object_key = ObjectKey::new(&key);

    let hk = HashKey::from_bytes(hash_key(object_key.as_str().as_bytes()));

    let req = WriteRequest {
        bucket: bucket_id,
        key: object_key,
        hash_key: hk,
        data: body,
        write_quorum: 2,
        ack_after_wal: true,
        ec_async: false,
        policy: None,
    };

    match state.write.put(req).await {
        Ok(result) => {
            let etag = result
                .blake3_hash
                .map(|h| h.to_hex())
                .unwrap_or_default();

            info!(key = %key, size = result.size, etag = %etag, "PUT object success");

            let mut headers = HeaderMap::new();
            headers.insert(header::ETAG, header_val(&etag));
            headers.insert(header::CONTENT_LENGTH, header_val("0"));

            (StatusCode::OK, headers).into_response()
        }
        Err(e) => s3_error_response(&e, &bucket, &key),
    }
}

/// GET /{bucket}/{key} — retrieve an object.
///
/// Delegates to [`ReadCoordinator::get`]. Returns the object body
/// with `Content-Type`, `ETag`, and `Content-Length` headers.
///
/// # Errors
///
/// Returns `404` with S3 XML if the object does not exist.
async fn get_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
) -> Response {
    let bucket_id = BucketId::new(&bucket);
    let object_key = ObjectKey::new(&key);

    let hk = HashKey::from_bytes(hash_key(object_key.as_str().as_bytes()));

    let req = ReadRequest {
        bucket: bucket_id,
        key: object_key,
        hash_key: hk,
        metadata_only: false,
        policy: None,
    };

    match state.read.get(req).await {
        Ok(result) => {
            let etag = result
                .metadata
                .blake3_hash
                .as_ref()
                .map(|h| h.to_hex())
                .unwrap_or_else(|| {
                    let hash = blake3::hash(&result.data);
                    oceanfs_core::HashOutput::from_bytes(*hash.as_bytes()).to_hex()
                });
            let content_type = infer_content_type(&state.mime_types, &key);

            info!(key = %key, size = result.data.len(), "GET object success");

            let mut headers = HeaderMap::new();
            headers.insert(header::CONTENT_TYPE, header_val(&content_type));
            headers.insert(header::ETAG, header_val(&etag));
            headers.insert(
                header::CONTENT_LENGTH,
                header_val(&result.data.len().to_string()),
            );

            (StatusCode::OK, headers, Body::from(result.data)).into_response()
        }
        Err(e) => s3_error_response(&e, &bucket, &key),
    }
}

/// HEAD /{bucket}/{key} — retrieve object metadata only.
///
/// Delegates to [`ReadCoordinator::get`] with `metadata_only = true`.
/// Returns headers without a response body.
///
/// # Errors
///
/// Returns `404` if the object does not exist.
async fn head_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
) -> Response {
    let bucket_id = BucketId::new(&bucket);
    let object_key = ObjectKey::new(&key);

    let hk = HashKey::from_bytes(hash_key(object_key.as_str().as_bytes()));

    let req = ReadRequest {
        bucket: bucket_id,
        key: object_key,
        hash_key: hk,
        metadata_only: true,
        policy: None,
    };

    match state.read.get(req).await {
        Ok(result) => {
            let etag = result
                .metadata
                .blake3_hash
                .as_ref()
                .map(|h| h.to_hex())
                .unwrap_or_default();
            let size = result.metadata.size;

            debug!(key = %key, size = size, "HEAD object success");

            let mut headers = HeaderMap::new();
            headers.insert(
                header::CONTENT_TYPE,
                header_val(&infer_content_type(&state.mime_types, &key)),
            );
            headers.insert(header::ETAG, header_val(&etag));
            headers.insert(header::CONTENT_LENGTH, header_val(&size.to_string()));
            headers.insert(header::ACCEPT_RANGES, header_val("bytes"));

            (StatusCode::OK, headers).into_response()
        }
        Err(e) => s3_error_response(&e, &bucket, &key),
    }
}

/// DELETE /{bucket}/{key} — soft-delete an object.
///
/// Writes a tombstone via [`MetadataOps::delete_object`].
/// Returns `204 No Content` on success.
///
/// # Errors
///
/// Returns `404` if the object does not exist.
async fn delete_object(
    State(state): State<AppState>,
    Path((bucket, key)): Path<(String, String)>,
) -> Response {
    let bucket_id = BucketId::new(&bucket);
    let object_key = ObjectKey::new(&key);

    match state.metadata.delete_object(&bucket_id, &object_key) {
        Ok(()) => {
            info!(key = %key, "DELETE object success");
            StatusCode::NO_CONTENT.into_response()
        }
        Err(e) => {
            let srv_err = Error::Metadata(e);
            s3_error_response(&srv_err, &bucket, &key)
        }
    }
}

// ---------------------------------------------------------------------------
// Bucket handlers
// ---------------------------------------------------------------------------

/// PUT /{bucket} — create a new bucket with default policy.
///
/// # Errors
///
/// Returns `409` if the bucket already exists.
async fn create_bucket(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
) -> Response {
    if state.buckets.exists(&bucket) {
        let err = Error::BucketAlreadyExists(bucket.clone());
        return s3_error_response(&err, &bucket, "");
    }

    state.buckets.put(bucket.clone(), crate::bucket_config::BucketPolicy::default());
    info!(bucket = %bucket, "bucket created");

    let mut headers = HeaderMap::new();
    headers.insert(header::LOCATION, header_val(&format!("/{}", bucket)));
    (StatusCode::OK, headers).into_response()
}

/// GET /{bucket}?list-type=2&prefix=... — list objects in a bucket.
///
/// Supports `prefix` query parameter. Returns an S3-compatible
/// `ListBucketResult` XML response.
///
/// # Errors
///
/// Returns `404` if the bucket does not exist.
async fn list_objects(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
    Query(params): Query<HashMap<String, String>>,
) -> Response {
    let bucket_id = BucketId::new(&bucket);
    let prefix = params.get("prefix").map(|s| s.as_str()).unwrap_or("");

    match state.metadata.list_objects(&bucket_id, prefix) {
        Ok(objects) => {
            let entries: Vec<(String, u64, String)> = objects
                .iter()
                .map(|m| {
                    let etag = m
                        .blake3_hash
                        .as_ref()
                        .map(|h| h.to_hex())
                        .unwrap_or_default();
                    (m.object_key.as_str().to_string(), m.size, etag)
                })
                .collect();

            let xml = s3_xml::list_bucket_xml(&bucket, &entries, false, None, prefix);
            let mut headers = HeaderMap::new();
            headers.insert(header::CONTENT_TYPE, header_val("application/xml"));
            (StatusCode::OK, headers, Body::from(xml)).into_response()
        }
        Err(e) => {
            let srv_err = Error::Metadata(e);
            s3_error_response(&srv_err, &bucket, "")
        }
    }
}

/// DELETE /{bucket} — delete an empty bucket.
///
/// # Errors
///
/// Returns `409` if the bucket is not empty.
/// Returns `404` if the bucket does not exist.
async fn delete_bucket(
    State(state): State<AppState>,
    Path(bucket): Path<String>,
) -> Response {
    if !state.buckets.exists(&bucket) {
        let err = Error::NotFound(format!("bucket {bucket}"));
        return s3_error_response(&err, &bucket, "");
    }

    // Check if bucket is empty by listing with no prefix.
    let bucket_id = BucketId::new(&bucket);
    match state.metadata.list_objects(&bucket_id, "") {
        Ok(objects) if !objects.is_empty() => {
            let err = Error::BucketNotEmpty(bucket.clone());
            s3_error_response(&err, &bucket, "")
        }
        Ok(_) => {
            state.buckets.delete(&bucket);
            info!(bucket = %bucket, "bucket deleted");
            StatusCode::NO_CONTENT.into_response()
        }
        Err(e) => {
            let srv_err = Error::Metadata(e);
            s3_error_response(&srv_err, &bucket, "")
        }
    }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Builds an S3-compatible XML error response from a server error.
fn s3_error_response(err: &Error, bucket: &str, key: &str) -> Response {
    let resource = if key.is_empty() {
        bucket.to_string()
    } else {
        format!("{}/{}", bucket, key)
    };

    let status = err.s3_status();
    let code = err.s3_code();
    let message = err.s3_message();
    let request_id = uuid_for_error();
    let body = s3_xml::s3_error_xml(code, &message, &resource, &request_id);

    error!(
        status = status.as_u16(),
        code = code,
        message = %message,
        "S3 error response"
    );

    let mut headers = HeaderMap::new();
    headers.insert(header::CONTENT_TYPE, header_val("application/xml"));
    (status, headers, Body::from(body)).into_response()
}

/// Generates a short request ID for error XML bodies.
fn uuid_for_error() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!("{:016x}", ts % 0xFFFFFFFFFFFFFFFFu128)
}

/// Infers a MIME content type from the file extension.
fn infer_content_type(mime_map: &MimeMap, key: &str) -> String {
    mime_map.guess(key)
}

// ---------------------------------------------------------------------------
// MIME type map
// ---------------------------------------------------------------------------

/// A map from file extensions to MIME types.
///
/// Used to set the `Content-Type` header on GET and HEAD responses.
/// The default configuration covers common web and media types.
#[derive(Debug)]
pub struct MimeMap {
    /// Extension → MIME type mapping (extension without dot).
    map: HashMap<String, String>,
}

impl MimeMap {
    /// Creates a new `MimeMap` with default common MIME types.
    pub fn new() -> Self {
        let mut map = HashMap::new();
        // Text
        map.insert("html".into(), "text/html".into());
        map.insert("htm".into(), "text/html".into());
        map.insert("css".into(), "text/css".into());
        map.insert("js".into(), "application/javascript".into());
        map.insert("txt".into(), "text/plain".into());
        map.insert("csv".into(), "text/csv".into());
        map.insert("xml".into(), "application/xml".into());
        map.insert("json".into(), "application/json".into());
        // Images
        map.insert("jpg".into(), "image/jpeg".into());
        map.insert("jpeg".into(), "image/jpeg".into());
        map.insert("png".into(), "image/png".into());
        map.insert("gif".into(), "image/gif".into());
        map.insert("svg".into(), "image/svg+xml".into());
        map.insert("webp".into(), "image/webp".into());
        // Audio/Video
        map.insert("mp3".into(), "audio/mpeg".into());
        map.insert("mp4".into(), "video/mp4".into());
        map.insert("webm".into(), "video/webm".into());
        // Documents
        map.insert("pdf".into(), "application/pdf".into());
        map.insert("zip".into(), "application/zip".into());
        map.insert("gz".into(), "application/gzip".into());
        map.insert("tar".into(), "application/x-tar".into());
        // Binary
        map.insert("wasm".into(), "application/wasm".into());
        Self { map }
    }

    /// Guesses the MIME type from a key (file name or path).
    ///
    /// Returns `"application/octet-stream"` if the extension
    /// is not recognized.
    pub fn guess(&self, key: &str) -> String {
        if let Some(dot_pos) = key.rfind('.') {
            let ext = &key[(dot_pos + 1)..];
            self.map
                .get(ext)
                .cloned()
                .unwrap_or_else(|| "application/octet-stream".into())
        } else {
            "application/octet-stream".into()
        }
    }
}

impl Default for MimeMap {
    fn default() -> Self {
        Self::new()
    }
}

