//! Column family names and key encoding for the metadata store.

/// Column family name for object metadata.
pub(crate) const CF_OBJECTS: &str = "objects";

/// Column family name for segment metadata.
pub(crate) const CF_SEGMENTS: &str = "segments";

/// Column family name for deletion tombstones.
pub(crate) const CF_DELETIONS: &str = "deletions";

/// All column families used by the metadata store.
pub(crate) const ALL_COLUMN_FAMILIES: &[&str] = &[CF_OBJECTS, CF_SEGMENTS, CF_DELETIONS];

/// Encodes a bucket and object key into a RocksDB key.
///
/// Format: `{bucket_name}\0{object_key}`
pub(crate) fn encode_object_key(bucket: &str, key: &str) -> Vec<u8> {
    let mut buf = Vec::with_capacity(bucket.len() + 1 + key.len());
    buf.extend_from_slice(bucket.as_bytes());
    buf.push(0);
    buf.extend_from_slice(key.as_bytes());
    buf
}

/// Decodes a RocksDB key back into bucket and object key components.
#[allow(dead_code)]
pub(crate) fn decode_object_key(data: &[u8]) -> Option<(&str, &str)> {
    let null_pos = data.iter().position(|&b| b == 0)?;
    let bucket = std::str::from_utf8(&data[..null_pos]).ok()?;
    let key = std::str::from_utf8(&data[null_pos + 1..]).ok()?;
    Some((bucket, key))
}

/// Encodes a segment ID into a RocksDB key.
///
/// Format: `segment:{uuid_bytes}`
pub(crate) fn encode_segment_key(id: &oceanfs_core::SegmentId) -> Vec<u8> {
    let mut buf = Vec::with_capacity(24);
    buf.extend_from_slice(b"segment:");
    buf.extend_from_slice(id.as_uuid().as_bytes());
    buf
}

/// Encodes a bucket and object key into a deletion tombstone key.
#[allow(dead_code)]
pub(crate) fn encode_deletion_key(bucket: &str, key: &str) -> Vec<u8> {
    // Same format as object keys — deletions are looked up by the same key.
    encode_object_key(bucket, key)
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;

    #[test]
    fn object_key_roundtrip() {
        let encoded = encode_object_key("photos", "cat.jpg");
        let (bucket, key) = decode_object_key(&encoded).unwrap();
        assert_eq!(bucket, "photos");
        assert_eq!(key, "cat.jpg");
    }

    #[test]
    fn object_key_handles_empty_parts() {
        let encoded = encode_object_key("", "");
        let (bucket, key) = decode_object_key(&encoded).unwrap();
        assert_eq!(bucket, "");
        assert_eq!(key, "");
    }

    #[test]
    fn segment_key_is_unique_per_id() {
        let id1 = oceanfs_core::SegmentId::new();
        let id2 = oceanfs_core::SegmentId::new();
        assert_ne!(encode_segment_key(&id1), encode_segment_key(&id2));
    }
}

//! RocksDB-backed metadata persistence.
//!
//! Stores object metadata, segment metadata, and deletion tombstones
//! in three RocksDB column families. Provides strongly-typed CRUD
//! operations with batch atomic writes and prefix-range scans.

mod cf;
mod store;

pub use store::{BatchOp, MetadataStore};

//! RocksDB-backed metadata store with strongly-typed CRUD.

use std::sync::Arc;

use oceanfs_core::{
    BucketId, MetadataConfig, ObjectKey, ObjectMetadata, SegmentId, SegmentMetadata, Tombstone,
};
use rocksdb::{ColumnFamilyDescriptor, Options, DB};

use crate::{
    error::{Error, Result},
    metadata::cf,
};

/// A RocksDB-backed metadata store with three column families.
///
/// Manages object metadata (`objects` CF), segment metadata (`segments` CF),
/// and deletion tombstones (`deletions` CF).
///
/// # Examples
///
/// ```ignore
/// // Requires a running RocksDB instance; examples are in unit tests.
/// use oceanfs_core::{MetadataConfig, ObjectKey, BucketId, Hlc};
/// use oceanfs_storage::MetadataStore;
/// let config = MetadataConfig::default();
/// let store = MetadataStore::open(&config).unwrap();
/// ```
pub struct MetadataStore {
    db: Arc<DB>,
}

fn io_err(e: impl std::error::Error) -> std::io::Error {
    std::io::Error::other(e.to_string())
}

impl MetadataStore {
    /// Opens or creates a metadata store at the given data directory.
    ///
    /// # Errors
    ///
    /// Returns an error if RocksDB cannot open the database or create
    /// the required column families.
    ///
    /// # Panics
    ///
    /// Panics if a column family handle is missing after creation
    /// (indicates a programming error).
    pub fn open(config: &MetadataConfig) -> Result<Self> {
        std::fs::create_dir_all(&config.data_dir)?;

        let mut opts = Options::default();
        opts.create_if_missing(true);
        opts.create_missing_column_families(true);
        opts.set_compression_type(rocksdb::DBCompressionType::Zstd);
        opts.increase_parallelism(num_cpus::get() as i32);
        opts.optimize_level_style_compaction(config.memtable_size);

        // Configure block cache.
        let block_cache =
            rocksdb::Cache::new_lru_cache(config.block_cache_size);
        let mut block_opts = rocksdb::BlockBasedOptions::default();
        block_opts.set_block_cache(&block_cache);

        let cf_descriptors: Vec<ColumnFamilyDescriptor> = cf::ALL_COLUMN_FAMILIES
            .iter()
            .map(|&name| {
                let mut cf_opts = Options::default();
                cf_opts.set_compression_type(rocksdb::DBCompressionType::Zstd);
                cf_opts.set_block_based_table_factory(&block_opts);
                ColumnFamilyDescriptor::new(name, cf_opts)
            })
            .collect();

        let db = DB::open_cf_descriptors(&opts, &config.data_dir, cf_descriptors)
            .map_err(|e| Error::Io(io_err(e)))?;

        Ok(Self { db: Arc::new(db) })
    }

    // ------------------------------------------------------------------
    // Object operations
    // ------------------------------------------------------------------

    /// Stores object metadata.
    ///
    /// # Errors
    ///
    /// Returns an error if the underlying RocksDB write fails.
    pub fn put_object(&self, meta: ObjectMetadata) -> Result<()> {
        let cf = self
            .db
            .cf_handle(cf::CF_OBJECTS)
            .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;

        let key = cf::encode_object_key("default", meta.object_key.as_str());
        let value = serde_json::to_vec(&meta).map_err(|e| Error::Io(io_err(e)))?;

        self.db.put_cf(&cf, key, value).map_err(|e| Error::Io(io_err(e)))?;

        Ok(())
    }

    /// Retrieves object metadata.
    ///
    /// Returns `None` if the object does not exist.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB read or deserialization fails.
    pub fn get_object(&self, bucket: &BucketId, key: &ObjectKey) -> Result<Option<ObjectMetadata>> {
        let cf = self
            .db
            .cf_handle(cf::CF_OBJECTS)
            .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;

        let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());

        match self.db.get_cf(&cf, db_key) {
            Ok(Some(value)) => {
                let meta: ObjectMetadata =
                    serde_json::from_slice(&value).map_err(|e| Error::Io(io_err(e)))?;
                Ok(Some(meta))
            }
            Ok(None) => Ok(None),
            Err(e) => Err(Error::Io(io_err(e))),
        }
    }

    /// Deletes object metadata.
    ///
    /// This is a soft delete — the data remains in segments until GC.
    /// Use [`Self::put_tombstone`] to record the deletion for GC.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB delete fails.
    pub fn delete_object(&self, bucket: &BucketId, key: &ObjectKey) -> Result<()> {
        let cf = self
            .db
            .cf_handle(cf::CF_OBJECTS)
            .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;

        let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());

        self.db.delete_cf(&cf, db_key).map_err(|e| Error::Io(io_err(e)))?;

        Ok(())
    }

    /// Lists objects whose keys start with the given prefix.
    ///
    /// Results are in key order. Suitable for S3 `LIST` operations.
    ///
    /// # Errors
    ///
    /// Individual entries that fail to deserialize are skipped.
    pub fn list_objects(&self, bucket: &BucketId, prefix: &str) -> Vec<Result<ObjectMetadata>> {
        let cf = self.db.cf_handle(cf::CF_OBJECTS);
        let Some(cf_handle) = cf else {
            return vec![];
        };
        let prefix_key = cf::encode_object_key(bucket.as_str(), prefix);

        let iter = self.db.iterator_cf(
            &cf_handle,
            rocksdb::IteratorMode::From(&prefix_key, rocksdb::Direction::Forward),
        );

        iter.take_while(
            move |item| {
                if let Ok((key, _)) = item {
                    key.starts_with(&prefix_key)
                } else {
                    false
                }
            },
        )
        .filter_map(|item| match item {
            Ok((_key, value)) => match serde_json::from_slice::<ObjectMetadata>(&value) {
                Ok(meta) => Some(Ok(meta)),
                Err(_) => None,
            },
            Err(e) => Some(Err(Error::Io(io_err(e)))),
        })
        .collect()
    }

    // ------------------------------------------------------------------
    // Segment operations
    // ------------------------------------------------------------------

    /// Stores segment metadata.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB write fails.
    pub fn put_segment(&self, meta: SegmentMetadata) -> Result<()> {
        let cf = self
            .db
            .cf_handle(cf::CF_SEGMENTS)
            .ok_or_else(|| Error::InvalidConfig("segments CF not found".into()))?;

        let key = cf::encode_segment_key(&meta.segment_id);
        let value = serde_json::to_vec(&meta).map_err(|e| Error::Io(io_err(e)))?;

        self.db.put_cf(&cf, key, value).map_err(|e| Error::Io(io_err(e)))?;

        Ok(())
    }

    /// Retrieves segment metadata.
    ///
    /// Returns `None` if the segment does not exist.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB read or deserialization fails.
    pub fn get_segment(&self, id: SegmentId) -> Result<Option<SegmentMetadata>> {
        let cf = self
            .db
            .cf_handle(cf::CF_SEGMENTS)
            .ok_or_else(|| Error::InvalidConfig("segments CF not found".into()))?;

        let key = cf::encode_segment_key(&id);

        match self.db.get_cf(&cf, key) {
            Ok(Some(value)) => {
                let meta: SegmentMetadata =
                    serde_json::from_slice(&value).map_err(|e| Error::Io(io_err(e)))?;
                Ok(Some(meta))
            }
            Ok(None) => Ok(None),
            Err(e) => Err(Error::Io(io_err(e))),
        }
    }

    /// Lists all segment metadata entries.
    ///
    /// # Errors
    ///
    /// Individual entries that fail to deserialize are skipped.
    pub fn list_segments(&self) -> Vec<Result<SegmentMetadata>> {
        let cf = self.db.cf_handle(cf::CF_SEGMENTS);
        let Some(cf_handle) = cf else {
            return vec![];
        };

        let iter = self.db.iterator_cf(&cf_handle, rocksdb::IteratorMode::Start);

        iter.filter_map(|item| match item {
            Ok((_key, value)) => match serde_json::from_slice::<SegmentMetadata>(&value) {
                Ok(meta) => Some(Ok(meta)),
                Err(_) => None,
            },
            Err(e) => Some(Err(Error::Io(io_err(e)))),
        })
        .collect()
    }

    // ------------------------------------------------------------------
    // Tombstone operations
    // ------------------------------------------------------------------

    /// Records a deletion tombstone.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB write fails.
    pub fn put_tombstone(
        &self,
        bucket: &BucketId,
        key: &ObjectKey,
        tombstone: Tombstone,
    ) -> Result<()> {
        let cf = self
            .db
            .cf_handle(cf::CF_DELETIONS)
            .ok_or_else(|| Error::InvalidConfig("deletions CF not found".into()))?;

        let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());
        let value = serde_json::to_vec(&tombstone).map_err(|e| Error::Io(io_err(e)))?;

        self.db.put_cf(&cf, db_key, value).map_err(|e| Error::Io(io_err(e)))?;

        Ok(())
    }

    /// Checks if a deletion tombstone exists.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB read fails.
    pub fn has_tombstone(&self, bucket: &BucketId, key: &ObjectKey) -> Result<bool> {
        let cf = self
            .db
            .cf_handle(cf::CF_DELETIONS)
            .ok_or_else(|| Error::InvalidConfig("deletions CF not found".into()))?;

        let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());

        match self.db.get_cf(&cf, db_key) {
            Ok(Some(_)) => Ok(true),
            Ok(None) => Ok(false),
            Err(e) => Err(Error::Io(io_err(e))),
        }
    }

    // ------------------------------------------------------------------
    // Async wrappers
    // ------------------------------------------------------------------

    /// Async version of [`Self::put_object`].
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB write fails or the blocking
    /// task panics.
    pub async fn put_object_async(&self, meta: ObjectMetadata) -> Result<()> {
        let db = self.db.clone();
        tokio::task::spawn_blocking(move || {
            let cf = db
                .cf_handle(cf::CF_OBJECTS)
                .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;
            let key = cf::encode_object_key("default", meta.object_key.as_str());
            let value = serde_json::to_vec(&meta).map_err(|e| Error::Io(io_err(e)))?;
            db.put_cf(&cf, key, value).map_err(|e| Error::Io(io_err(e)))?;
            Ok(())
        })
        .await
        .map_err(|e| Error::Io(std::io::Error::other(e.to_string())))?
    }

    /// Async version of [`Self::get_object`].
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB read fails or the blocking
    /// task panics.
    pub async fn get_object_async(
        &self,
        bucket: BucketId,
        key: ObjectKey,
    ) -> Result<Option<ObjectMetadata>> {
        let db = self.db.clone();
        tokio::task::spawn_blocking(move || {
            let cf = db
                .cf_handle(cf::CF_OBJECTS)
                .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;
            let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());
            match db.get_cf(&cf, db_key) {
                Ok(Some(value)) => {
                    let meta: ObjectMetadata =
                        serde_json::from_slice(&value).map_err(|e| Error::Io(io_err(e)))?;
                    Ok(Some(meta))
                }
                Ok(None) => Ok(None),
                Err(e) => Err(Error::Io(io_err(e))),
            }
        })
        .await
        .map_err(|e| Error::Io(std::io::Error::other(e.to_string())))?
    }

    /// Async version of [`Self::delete_object`].
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB delete fails or the blocking
    /// task panics.
    pub async fn delete_object_async(&self, bucket: BucketId, key: ObjectKey) -> Result<()> {
        let db = self.db.clone();
        tokio::task::spawn_blocking(move || {
            let cf = db
                .cf_handle(cf::CF_OBJECTS)
                .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;
            let db_key = cf::encode_object_key(bucket.as_str(), key.as_str());
            db.delete_cf(&cf, db_key).map_err(|e| Error::Io(io_err(e)))?;
            Ok(())
        })
        .await
        .map_err(|e| Error::Io(std::io::Error::other(e.to_string())))?
    }

    // ------------------------------------------------------------------
    // Batch operations
    // ------------------------------------------------------------------

    /// Atomically writes a batch of metadata operations.
    ///
    /// All put/delete operations in the batch succeed or fail together.
    ///
    /// # Errors
    ///
    /// Returns an error if the RocksDB write batch fails.
    pub fn batch_write(&self, ops: Vec<BatchOp>) -> Result<()> {
        let mut batch = rocksdb::WriteBatch::default();

        for op in &ops {
            match op {
                BatchOp::PutObject(key, value) => {
                    let cf = self
                        .db
                        .cf_handle(cf::CF_OBJECTS)
                        .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;
                    let k = cf::encode_object_key("default", key.as_str());
                    let v = serde_json::to_vec(value).map_err(|e| Error::Io(io_err(e)))?;
                    batch.put_cf(&cf, k, v);
                }
                BatchOp::DeleteObject(bucket, key) => {
                    let cf = self
                        .db
                        .cf_handle(cf::CF_OBJECTS)
                        .ok_or_else(|| Error::InvalidConfig("objects CF not found".into()))?;
                    let k = cf::encode_object_key(bucket.as_str(), key.as_str());
                    batch.delete_cf(&cf, k);
                }
                BatchOp::PutTombstone(bucket, key, tombstone) => {
                    let cf = self
                        .db
                        .cf_handle(cf::CF_DELETIONS)
                        .ok_or_else(|| Error::InvalidConfig("deletions CF not found".into()))?;
                    let k = cf::encode_object_key(bucket.as_str(), key.as_str());
                    let v = serde_json::to_vec(tombstone).map_err(|e| Error::Io(io_err(e)))?;
                    batch.put_cf(&cf, k, v);
                }
                BatchOp::PutSegment(meta) => {
                    let cf = self
                        .db
                        .cf_handle(cf::CF_SEGMENTS)
                        .ok_or_else(|| Error::InvalidConfig("segments CF not found".into()))?;
                    let k = cf::encode_segment_key(&meta.segment_id);
                    let v = serde_json::to_vec(meta).map_err(|e| Error::Io(io_err(e)))?;
                    batch.put_cf(&cf, k, v);
                }
            }
        }

        self.db.write(batch).map_err(|e| Error::Io(io_err(e)))?;

        Ok(())
    }
}

/// An operation in a batch write.
#[derive(Debug, Clone)]
pub enum BatchOp {
    /// Put an object metadata entry.
    PutObject(ObjectKey, ObjectMetadata),
    /// Delete an object.
    DeleteObject(BucketId, ObjectKey),
    /// Put a tombstone.
    PutTombstone(BucketId, ObjectKey, Tombstone),
    /// Put a segment metadata entry.
    PutSegment(SegmentMetadata),
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use oceanfs_core::{HashOutput, Hlc, SizeTier};

    use super::*;

    fn test_config() -> MetadataConfig {
        let dir = tempfile::tempdir().unwrap();
        MetadataConfig {
            data_dir: dir.path().to_path_buf(),
            block_cache_size: 8 * 1024 * 1024,
            memtable_size: 8 * 1024 * 1024,
        }
    }

    fn make_object_meta(key: &str, size: u64, inline: Option<&[u8]>) -> ObjectMetadata {
        ObjectMetadata {
            object_key: ObjectKey::new(key),
            size,
            blake3_hash: Some(HashOutput::from_bytes([0u8; 32])),
            chunks: smallvec::SmallVec::new(),
            inline_data: inline.map(bytes::Bytes::copy_from_slice),
            created_at: 1700000000000,
            hlc: Hlc::new(1700000000000, 0),
        }
    }

    #[test]
    fn put_and_get_object_roundtrip() {
        let store = MetadataStore::open(&test_config()).unwrap();
        let meta = make_object_meta("photo.jpg", 1024, Some(b"inline-data"));
        store.put_object(meta.clone()).unwrap();

        let got = store
            .get_object(&BucketId::new("default"), &ObjectKey::new("photo.jpg"))
            .unwrap()
            .unwrap();
        assert_eq!(got.object_key.as_str(), "photo.jpg");
        assert_eq!(got.size, 1024);
        assert!(got.is_inline());
    }

    #[test]
    fn get_nonexistent_object_returns_none() {
        let store = MetadataStore::open(&test_config()).unwrap();
        let result = store.get_object(&BucketId::new("default"), &ObjectKey::new("nope")).unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn delete_object_removes_it() {
        let store = MetadataStore::open(&test_config()).unwrap();
        let meta = make_object_meta("temp.txt", 100, None);
        store.put_object(meta).unwrap();
        store.delete_object(&BucketId::new("default"), &ObjectKey::new("temp.txt")).unwrap();

        let result =
            store.get_object(&BucketId::new("default"), &ObjectKey::new("temp.txt")).unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn list_objects_by_prefix() {
        let store = MetadataStore::open(&test_config()).unwrap();

        for name in &["a/1.txt", "a/2.txt", "b/3.txt"] {
            store.put_object(make_object_meta(name, 10, None)).unwrap();
        }

        let results = store.list_objects(&BucketId::new("default"), "a/");
        let results: Vec<_> = results.into_iter().collect::<Result<Vec<_>>>().unwrap();
        assert_eq!(results.len(), 2);
    }

    #[test]
    fn put_and_get_segment_roundtrip() {
        let store = MetadataStore::open(&test_config()).unwrap();
        let meta = SegmentMetadata {
            segment_id: SegmentId::new(),
            ec_k: 4,
            ec_m: 2,
            size_tier: SizeTier::Standard,
            merkle_root: None,
            storage_locations: smallvec::SmallVec::new(),
            sealed_at: Some(1700000000000),
        };
        store.put_segment(meta.clone()).unwrap();

        let got = store.get_segment(meta.segment_id).unwrap().unwrap();
        assert_eq!(got.ec_k, 4);
        assert_eq!(got.ec_m, 2);
        assert!(got.is_sealed());
    }

    #[test]
    fn tombstone_roundtrip() {
        let store = MetadataStore::open(&test_config()).unwrap();
        let bucket = BucketId::new("default");
        let key = ObjectKey::new("deleted.txt");

        store
            .put_tombstone(
                &bucket,
                &key,
                Tombstone { deletion_time: 1700000000000, hlc: Hlc::new(1700000000000, 1) },
            )
            .unwrap();

        assert!(store.has_tombstone(&bucket, &key).unwrap());
    }

    #[test]
    fn no_tombstone_for_nonexistent_key() {
        let store = MetadataStore::open(&test_config()).unwrap();
        assert!(!store.has_tombstone(&BucketId::new("default"), &ObjectKey::new("nope")).unwrap());
    }
}

//! Distributed scrubbing — full cluster-wide segment scan for integrity.
//!
//! Unlike anti-entropy's peer-to-peer incremental check, scrubbing is a
//! full cluster-wide scan of every segment, verifying BLAKE3 hashes and
//! Merkle roots. A randomly elected coordinator partitions the segment ID
//! space across all healthy nodes. Each node scrubs its partition, reports
//! discrepancies, and auto-heals via EC decode.

use std::sync::Arc;

use oceanfs_core::{SegmentId, SegmentMetadata};
use tokio::sync::Semaphore;

use crate::error::{Error, Result};
use crate::metadata::MetadataStore;

// ---------------------------------------------------------------------------
// ScrubConfig
// ---------------------------------------------------------------------------

/// Configuration for distributed scrubbing.
///
/// # Examples
///
/// ```
/// # use oceanfs_storage::ScrubConfig;
/// let config = ScrubConfig::default();
/// assert_eq!(config.interval_sec(), 604800);
/// ```
#[derive(Debug, Clone)]
pub struct ScrubConfig {
    /// Interval between scrub cycles in seconds.
    interval_sec: u64,
    /// Maximum number of nodes participating (0 = all).
    parallel_nodes: usize,
    /// Throughput limit in bytes per second (0 = unlimited).
    throttle_bytes_sec: u64,
}

impl Default for ScrubConfig {
    fn default() -> Self {
        Self { interval_sec: 604800, parallel_nodes: 0, throttle_bytes_sec: 0 }
    }
}

impl ScrubConfig {
    /// Returns the scrub interval in seconds.
    pub fn interval_sec(&self) -> u64 {
        self.interval_sec
    }

    /// Returns the maximum number of parallel nodes.
    pub fn parallel_nodes(&self) -> usize {
        self.parallel_nodes
    }

    /// Returns the throughput throttle in bytes per second.
    pub fn throttle_bytes_sec(&self) -> u64 {
        self.throttle_bytes_sec
    }
}

// ---------------------------------------------------------------------------
// ScrubReport
// ---------------------------------------------------------------------------

/// Results from a full scrub cycle.
#[derive(Debug, Default, Clone)]
pub struct ScrubReport {
    /// Total segments examined.
    pub segments_total: u64,
    /// Segments verified healthy.
    pub segments_healthy: u64,
    /// Segments found to be corrupt.
    pub segments_corrupt: u64,
    /// Segments successfully healed.
    pub segments_healed: u64,
    /// Total bytes scanned.
    pub bytes_scanned: u64,
    /// Number of nodes that participated.
    pub nodes_participated: usize,
    /// Duration of the scrub cycle in seconds.
    pub duration_sec: f64,
}

// ---------------------------------------------------------------------------
// ScrubResult
// ---------------------------------------------------------------------------

/// Result of scrubbing a single segment.
#[derive(Debug, Clone)]
#[allow(dead_code)]
pub(crate) struct ScrubResult {
    /// The segment ID that was scrubbed.
    pub segment_id: SegmentId,
    /// Whether the segment verified as healthy.
    pub healthy: bool,
    /// Indices of corrupt shards (empty if healthy).
    pub corrupt_shard_indices: Vec<usize>,
    /// Whether the Merkle root mismatched.
    pub merkle_mismatch: bool,
}

// ---------------------------------------------------------------------------
// SegmentPartition
// ---------------------------------------------------------------------------

/// A partition of the segment ID space assigned to a single node.
#[derive(Debug, Clone)]
#[allow(dead_code)]
pub(crate) struct SegmentPartition {
    /// The node ID responsible for this partition.
    pub node_id: oceanfs_core::NodeId,
    /// The segment IDs in this partition.
    pub segment_ids: Vec<SegmentId>,
}

// ---------------------------------------------------------------------------
// ScrubWorker
// ---------------------------------------------------------------------------

/// Per-node task that reads assigned segment shards and verifies integrity.
#[allow(dead_code)]
pub(crate) struct ScrubWorker {
    metadata: Arc<MetadataStore>,
    throttle_bytes_sec: u64,
}

#[allow(dead_code)]
impl ScrubWorker {
    /// Creates a new scrub worker.
    pub(crate) fn new(metadata: Arc<MetadataStore>, throttle_bytes_sec: u64) -> Self {
        Self { metadata, throttle_bytes_sec }
    }

    /// Scrubs a single segment: verifies BLAKE3 hashes and Merkle root.
    ///
    /// In production, this would:
    /// 1. Read all local shards for this segment from disk
    /// 2. Compute BLAKE3 hash of each shard and compare to stored hashes
    /// 3. Recompute the Merkle tree from shard data and compare root to stored root
    /// 4. On mismatch: flag the shard as corrupt
    ///
    /// Returns the scrub result for this segment.
    pub(crate) fn scrub_segment(
        &self,
        segment_meta: &SegmentMetadata,
    ) -> ScrubResult {
        // In a production implementation:
        // - Read shard data from disk
        // - Compute BLAKE3 per shard
        // - Compare against stored hashes (from storage_locations or metadata)
        // - Recompute Merkle tree and compare root

        let corrupt_indices = Vec::new();
        let merkle_mismatch = false;

        // Verify Merkle root if present
        if let Some(stored_root) = segment_meta.merkle_root {
            // In production: recompute Merkle tree from segment data
            // For now, the verification is a placeholder
                tracing::debug!(
                    segment_id = %segment_meta.segment_id,
                    stored_root = %stored_root,
                    "verifying segment merkle root"
                );
            // Placeholder: assume healthy
        }

        // BLAKE3 verification of each shard
        // In production: iterate storage_locations, read shard data,
        // compute hash, compare against expected hash
        let healthy = corrupt_indices.is_empty() && !merkle_mismatch;

        ScrubResult {
            segment_id: segment_meta.segment_id,
            healthy,
            corrupt_shard_indices: corrupt_indices,
            merkle_mismatch,
        }
    }

    /// Scrubs a partition of segments and returns results.
    pub(crate) fn scrub_partition(
        &self,
        partition: &SegmentPartition,
    ) -> Vec<ScrubResult> {
        let mut results = Vec::with_capacity(partition.segment_ids.len());

        for seg_id in &partition.segment_ids {
            match self.metadata.get_segment(*seg_id) {
                Ok(Some(meta)) => {
                    let result = self.scrub_segment(&meta);
                    results.push(result);
                }
                Ok(None) => {
                    tracing::warn!(segment_id = %seg_id, "segment not found during scrub");
                }
                Err(e) => {
                    tracing::warn!(error = %e, segment_id = %seg_id, "failed to read segment during scrub");
                }
            }
        }

        results
    }
}

// ---------------------------------------------------------------------------
// ScrubCoordinator
// ---------------------------------------------------------------------------

/// Scrub coordinator — partitions segment space across nodes.
///
/// Elected per scrub cycle. Queries all segment IDs from metadata,
/// splits them into partitions, assigns each to a healthy node,
/// and aggregates results.
///
/// # Examples
///
/// ```
/// # use oceanfs_storage::{ScrubCoordinator, ScrubConfig};
/// let coord = ScrubCoordinator::new(ScrubConfig::default());
/// ```
pub struct ScrubCoordinator {
    config: ScrubConfig,
}

impl ScrubCoordinator {
    /// Creates a new scrub coordinator.
    pub fn new(config: ScrubConfig) -> Self {
        Self { config }
    }

    /// Returns the configuration.
    pub fn config(&self) -> &ScrubConfig {
        &self.config
    }

    /// Splits segment IDs into equal ranges across nodes. No gaps, no overlaps.
    #[allow(dead_code)]
    pub(crate) fn partition_segments(
        &self,
        segment_ids: &[SegmentId],
        node_ids: &[oceanfs_core::NodeId],
    ) -> Vec<SegmentPartition> {
        if node_ids.is_empty() || segment_ids.is_empty() {
            return Vec::new();
        }

        // Sort segment IDs for deterministic partitioning
        let mut sorted_ids: Vec<SegmentId> = segment_ids.to_vec();
        sorted_ids.sort();

        let node_count = node_ids.len();
        let segment_count = sorted_ids.len();
        let base_per_node = segment_count / node_count;
        let remainder = segment_count % node_count;

        let mut partitions = Vec::with_capacity(node_count);
        let mut start = 0;

        for (i, node_id) in node_ids.iter().enumerate() {
            let extra = if i < remainder { 1 } else { 0 };
            let count = base_per_node + extra;
            let end = (start + count).min(segment_count);

            let partition_ids = sorted_ids[start..end].to_vec();
            partitions.push(SegmentPartition { node_id: node_id.clone(), segment_ids: partition_ids });
            start = end;
        }

        partitions
    }

    /// Runs a single scrub cycle.
    ///
    /// In a real cluster this would:
    /// 1. Elect a coordinator (random node from membership)
    /// 2. Query all segment IDs from metadata
    /// 3. Partition segment space across nodes
    /// 4. Distribute partitions to workers on each node
    /// 5. Aggregate results into a ScrubReport
    ///
    /// For local testing, runs as a single-node scrub.
    ///
    /// # Errors
    ///
    /// Returns an error if metadata operations fail or the semaphore
    /// cannot be acquired.
    pub async fn run_cycle(
        &self,
        metadata: Arc<MetadataStore>,
    ) -> Result<ScrubReport> {
        use std::time::Instant;

        let start_time = Instant::now();
        let mut report = ScrubReport::default();

        // Phase 1: Gather all segment IDs
        let segments = metadata.list_segments();
        let segment_ids: Vec<SegmentId> = segments
            .into_iter()
            .filter_map(|r| r.ok().map(|s| s.segment_id))
            .collect();

        report.segments_total = segment_ids.len() as u64;

        if segment_ids.is_empty() {
            return Ok(report);
        }

        // Phase 2: For single-node/local scrub, verify each segment
        let semaphore = Arc::new(Semaphore::new(self.config.parallel_nodes.max(1)));
        let worker = Arc::new(ScrubWorker::new(
            metadata.clone(),
            self.config.throttle_bytes_sec,
        ));

        let partition = SegmentPartition {
            node_id: oceanfs_core::NodeId::new("local"),
            segment_ids: segment_ids.clone(),
        };

        // Acquire semaphore permit for bounded concurrency
        let _permit = semaphore.acquire().await.map_err(|e| {
            Error::Scrub(format!("semaphore acquire failed: {e}"))
        })?;

        let results = worker.scrub_partition(&partition);
        report.nodes_participated = 1;

        // Phase 3: Aggregate results
        for result in &results {
            report.bytes_scanned += 1; // placeholder: real impl tracks actual bytes
            if result.healthy {
                report.segments_healthy += 1;
            } else {
                report.segments_corrupt += 1;
            }
        }

        report.duration_sec = start_time.elapsed().as_secs_f64();

        tracing::info!(
            total = report.segments_total,
            healthy = report.segments_healthy,
            corrupt = report.segments_corrupt,
            duration_sec = report.duration_sec,
            "scrub cycle complete"
        );

        Ok(report)
    }

    /// Triggers a manual scrub (for admin API use).
    ///
    /// # Errors
    ///
    /// Returns an error if the background task cannot be spawned.
    pub async fn trigger_manual(
        &self,
        metadata: Arc<MetadataStore>,
    ) -> Result<()> {
        tokio::spawn({
            let this = Arc::new(Self { config: self.config.clone() });
            async move {
                match this.run_cycle(metadata).await {
                    Ok(report) => {
                        tracing::info!(
                            total = report.segments_total,
                            healthy = report.segments_healthy,
                            corrupt = report.segments_corrupt,
                            "manual scrub complete"
                        );
                    }
                    Err(e) => {
                        tracing::error!(error = %e, "manual scrub failed");
                    }
                }
            }
        });
        Ok(())
    }

    /// Starts the scrub background task.
    ///
    /// Runs cycles at the configured interval until cancelled.
    pub async fn start_background(
        self: Arc<Self>,
        metadata: Arc<MetadataStore>,
    ) -> tokio::task::JoinHandle<()> {
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(std::time::Duration::from_secs(self.config.interval_sec))
                    .await;
                match self.run_cycle(metadata.clone()).await {
                    Ok(report) => {
                        if report.segments_corrupt > 0 {
                            tracing::warn!(
                                corrupt = report.segments_corrupt,
                                "scrub detected corrupt segments"
                            );
                        }
                    }
                    Err(e) => {
                        tracing::warn!(error = %e, "scrub cycle failed");
                    }
                }
            }
        })
    }
}

