        assert_eq!(pool.slot_count(), 4);
        assert_eq!(pool.active_count(), 4, "all slots start in Appending state");
    }

    #[test]
    fn pool_append_returns_valid_offset_and_length() {
        let (pool_cfg, size_cfg) = test_config();
        let buf_pool = test_pool();
        let pool = SegmentPool::new(pool_cfg, SizeTier::Standard, &size_cfg, buf_pool).unwrap();
        let (seg_id, offset, length) = pool.append(b"hello world").unwrap();
        assert_eq!(offset, 0);
        assert_eq!(length, 11);
        assert_ne!(seg_id, SegmentId::default());
    }

    #[test]
    fn concurrent_writes_across_slots_do_not_corrupt_data() {
        let (pool_cfg, size_cfg) = test_config();
        let buf_pool = test_pool();
        let pool = StdArc::new(
            SegmentPool::new(pool_cfg, SizeTier::Standard, &size_cfg, buf_pool.clone()).unwrap(),
        );

        let write_count = StdArc::new(AtomicUsize::new(0));
        let num_threads = 8;
        let writes_per_thread = 50;

        let mut handles = Vec::with_capacity(num_threads);
        for _ in 0..num_threads {
            let pool = StdArc::clone(&pool);
            let write_count = StdArc::clone(&write_count);
            let handle = thread::spawn(move || {
                for _ in 0..writes_per_thread {
                    let result = pool.append(b"data");
                    assert!(result.is_ok(), "append must not fail under concurrency");
                    write_count.fetch_add(1, Ordering::Relaxed);
                }
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        assert_eq!(
            write_count.load(Ordering::Relaxed),
            num_threads * writes_per_thread
        );
    }

    #[test]
    fn encode_queue_is_created() {
        let (pool_cfg, size_cfg) = test_config();
        let buf_pool = test_pool();
        let pool = SegmentPool::new(pool_cfg, SizeTier::Standard, &size_cfg, buf_pool).unwrap();

        let rx = pool.take_encode_rx();
        assert!(rx.is_some(), "encode receiver must exist");
    }

    #[test]
    fn encode_semaphore_has_correct_permits() {
        let (pool_cfg, size_cfg) = test_config();
        let buf_pool = test_pool();
        let pool = SegmentPool::new(pool_cfg.clone(), SizeTier::Standard, &size_cfg, buf_pool.clone()).unwrap();

        let sem = pool.encode_semaphore();
        // Verify that the semaphore has been created with the expected count.
        // We can't directly inspect Semaphore internals, but we can acquire
        // all permits and then try one more.
        let mut permits = Vec::new();
        for _ in 0..pool_cfg.max_inflight_encodes {
            let permit = sem.try_acquire();
            assert!(permit.is_ok(), "should be able to acquire up to max permits");
            permits.push(permit.unwrap());
        }
        // One more should fail (no permits left).
        assert!(sem.try_acquire().is_err(), "should be exhausted");
    }

    #[test]
    fn custom_pool_size_config() {
        let pool_cfg = PoolConfig {
            active_pool_size: 8,
            ..PoolConfig::default()
        };
        let size_cfg = SegmentSizeConfig::default();
        let buf_pool = Arc::new(BufferPool::new(65536, 32));
        let pool = SegmentPool::new(pool_cfg, SizeTier::Small, &size_cfg, buf_pool).unwrap();
        assert_eq!(pool.slot_count(), 8);
    }

    #[test]
    fn pool_append_returns_different_segment_ids() {
        let pool_cfg = PoolConfig {
            active_pool_size: 2,
            ..PoolConfig::default()
        };
        let size_cfg = SegmentSizeConfig::default();
        let buf_pool = test_pool();
        let pool = SegmentPool::new(pool_cfg, SizeTier::Standard, &size_cfg, buf_pool).unwrap();

        let (id1, _, _) = pool.append(b"a").unwrap();
        // The second append may go to a different slot (round-robin).
        let (id2, _, _) = pool.append(b"b").unwrap();
        // Both IDs are valid UUIDs.
        assert_ne!(id1, SegmentId::default());
        assert_ne!(id2, SegmentId::default());
    }
}

//! Write-path orchestration — routes blob writes through the tier system.
//!
//! Contains `InlineWriter` for inline blob storage and the `route_write`
//! function that dispatches writes to the correct tier.

use bytes::Bytes;
use oceanfs_core::{ObjectKey, SizeTier};

use crate::{
    error::Result,
    metadata::MetadataStore,
    segment::{
        splitter::SegmentSplitter,
        tier::{ChunkListBuilder, TierRouter},
    },
};

/// Writes blobs directly to the metadata store (inline path).
#[allow(dead_code)]
pub(crate) struct InlineWriter;

impl InlineWriter {
    /// Stores a blob inline in metadata.
    ///
    /// # Errors
    ///
    /// Returns an error if the metadata write fails.
    #[allow(dead_code)]
    pub(crate) fn write_inline(
        metadata: &MetadataStore,
        key: ObjectKey,
        data: Bytes,
    ) -> Result<()> {
        let meta = oceanfs_core::ObjectMetadata {
            object_key: key,
            size: data.len() as u64,
            blake3_hash: None,
            chunks: smallvec::SmallVec::new(),
            inline_data: Some(data),
            created_at: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis() as i64,
            hlc: oceanfs_core::Hlc::zero(),
        };
        metadata.put_object(meta)
    }
}

/// Routes a blob write to the appropriate tier.
#[allow(dead_code)]
pub(crate) fn route_write(
    router: &TierRouter,
    metadata: &MetadataStore,
    active: &mut crate::segment::buffer::ActiveSegment,
    key: ObjectKey,
    data: Bytes,
) -> Result<smallvec::SmallVec<[oceanfs_core::ChunkRef; 4]>> {
    let blob_size = data.len() as u64;
    if blob_size == 0 {
        return Ok(smallvec::SmallVec::new());
    }

    let tier = router.classify(blob_size);

    match tier {
        SizeTier::Inline => {
            InlineWriter::write_inline(metadata, key, data)?;
            Ok(smallvec::SmallVec::new())
        }
        SizeTier::Small | SizeTier::Standard => {
            let segment_id = active.id();
            let (offset, length) = active.append(&data)?;
            Ok(ChunkListBuilder::single(segment_id, offset, length as u32))
        }
        SizeTier::Multi => {
            let splitter = SegmentSplitter::new(router.target_size(SizeTier::Multi));
            let chunks = splitter.split(&data);
            let mut refs = Vec::with_capacity(chunks.len());
            for (chunk_offset, chunk_data) in &chunks {
                let segment_id = active.id();
                let (_offset, _length) = active.append(chunk_data)?;
                refs.push((segment_id, *chunk_offset, chunk_data.len() as u32));
            }
            Ok(ChunkListBuilder::multi(refs))
        }
                  _ => Ok(smallvec::SmallVec::new()),
    }
}

