        let data = Bytes::from_static(b"tiny"); // 4 bytes ≤ 4096 → Inline
        let refs = route_write(&router, &metadata, &mut active, key.clone(), data.clone()).unwrap();

        assert!(refs.is_empty(), "inline blobs have no chunk refs");
        let fetched = metadata
            .get_object(&oceanfs_core::BucketId::new("default"), &key)
            .unwrap()
            .expect("object not found");
        assert!(fetched.is_inline());
        assert_eq!(fetched.inline_data.as_deref(), Some(&data[..]));
    }

    // ------------------------------------------------------------------
    // Small / Standard path
    // ------------------------------------------------------------------

    #[test]
    fn route_write_small_tier_returns_chunk_ref() {
        let metadata = test_config();
        // Custom config: inline threshold = 0 so 5KB goes to Small tier
        let config = SegmentSizeConfig {
            inline_threshold_bytes: 0,
            ..SegmentSizeConfig::default()
        };
        let router = TierRouter::new(config);
        let pool = test_pool(65536, 8);
        let mut active = crate::segment::buffer::ActiveSegment::new(
            SizeTier::Small,
            &SegmentSizeConfig::default(),
            &pool,
        ).unwrap();
        let key = ObjectKey::new("small-test");
        let data = Bytes::from(vec![0xCC; 5000]); // 5 KB → Small (≤256KB)

        let refs = route_write(&router, &metadata, &mut active, key, data).unwrap();

        assert_eq!(refs.len(), 1, "small blob should produce one chunk ref");
        assert_eq!(refs[0].offset, 0);
        assert_eq!(refs[0].length, 5000);
    }

    #[test]
    fn route_write_standard_tier_returns_chunk_ref() {
        let metadata = test_config();
        // 1 MB blob → Standard tier
        let router = TierRouter::new(SegmentSizeConfig::default());
        let pool = test_pool(65536, 8);
        let mut active = crate::segment::buffer::ActiveSegment::new(
            SizeTier::Standard,
            &SegmentSizeConfig::default(),
            &pool,
        ).unwrap();
        let key = ObjectKey::new("std-test");
        let data = Bytes::from(vec![0xDD; 1_048_576]); // 1 MB → Standard

        let refs = route_write(&router, &metadata, &mut active, key, data).unwrap();

        assert_eq!(refs.len(), 1, "standard blob should produce one chunk ref");
        assert_eq!(refs[0].offset, 0);
        assert_eq!(refs[0].length, 1_048_576);
    }

    // ------------------------------------------------------------------
    // Multi segment path
    // ------------------------------------------------------------------

    #[test]
    fn route_write_multi_tier_splits_into_chunks() {
        let metadata = test_config();
        // Custom config: default_target_size = 1 MB so 3 MB blob is Multi
        let config = SegmentSizeConfig {
            default_target_size: 1_048_576, // 1 MB
            ..SegmentSizeConfig::default()
        };
        let router = TierRouter::new(config);
        let pool = BufferPool::new(65536 * 16, 8); // larger pool for multi
        let mut active = crate::segment::buffer::ActiveSegment::new(
            SizeTier::Multi,
            &SegmentSizeConfig { default_target_size: 10_485_760, ..SegmentSizeConfig::default() },
            &pool,
        ).unwrap();
        let key = ObjectKey::new("multi-test");
        // 3 MB, each chunk is 1 MB (default_target_size)
        let data = Bytes::from(vec![0xEE; 3_145_728]);

        let refs = route_write(&router, &metadata, &mut active, key, data).unwrap();

        // 3 MB / 1 MB = 3 chunks
        assert_eq!(refs.len(), 3, "3 MB blob should split into 3 chunks");
        assert_eq!(refs[0].offset, 0);
        assert_eq!(refs[0].length, 1_048_576);
        assert_eq!(refs[1].offset, 1_048_576);
        assert_eq!(refs[1].length, 1_048_576);
        assert_eq!(refs[2].offset, 2_097_152);
        assert_eq!(refs[2].length, 1_048_576);
    }

    // ------------------------------------------------------------------
    // Edge cases
    // ------------------------------------------------------------------

    #[test]
    fn route_write_empty_blob_returns_empty_refs() {
        let metadata = test_config();
        let router = TierRouter::new(SegmentSizeConfig::default());
        let pool = test_pool(65536, 8);
        let mut active = crate::segment::buffer::ActiveSegment::new(
            SizeTier::Standard,
            &SegmentSizeConfig::default(),
            &pool,
        ).unwrap();
        let key = ObjectKey::new("empty");

        let refs = route_write(&router, &metadata, &mut active, key, Bytes::new()).unwrap();
        assert!(refs.is_empty());
    }
}

//! Segment sealer — finalizes active segments into immutable sealed segments.
//!
//! The sealer monitors active segments for fullness or timeout, builds the
//! blob index, writes the segment to disk, truncates the WAL, and persists
//! segment metadata to the metadata store.

use std::{path::PathBuf, sync::Arc};

use oceanfs_core::SegmentMetadata;
#[cfg(test)]
use oceanfs_core::{SegmentSizeConfig, SizeTier};

use crate::{
    error::{Error, Result},
    metadata::MetadataStore,
    segment::{
        buffer::ActiveSegment,
        handle::SegmentHandle,
        header::SegmentHeader,
        index::{SegmentIndex, SegmentIndexEntry},
    },
    wal::WalWriter,
};

/// Configuration for the segment sealer.
#[derive(Debug, Clone)]
#[allow(dead_code)]
pub struct SealConfig {
    /// Target size in bytes — seal when the segment exceeds this.
    pub target_size_bytes: u64,
    /// Maximum time in milliseconds before sealing a non-empty segment.
    pub seal_timeout_ms: u64,
    /// Directory where sealed segment files are written.
    pub data_dir: PathBuf,
}

/// Orchestrates the sealing of active segments.
/// Orchestrates the sealing of active segments.
#[allow(dead_code)]
pub struct SegmentSealer {
    config: SealConfig,
    metadata: Arc<MetadataStore>,
    wal: Arc<WalWriter>,
}

#[allow(dead_code)]
impl SegmentSealer {
    /// Creates a new segment sealer.
    pub fn new(
        config: SealConfig,
        metadata: Arc<MetadataStore>,
        wal: Arc<WalWriter>,
    ) -> Self {
        Self { config, metadata, wal }
    }

    /// Attempts to seal an active segment.
    ///
    /// `entries` are the blob index entries mapping (offset, length, hash) for
    /// each blob stored in this segment. The caller (write path) computes the
    /// blob key hashes.
    ///
    /// Returns `None` if the segment is not ready to seal (not full, not timed out,
    /// or empty). Returns a `SegmentHandle` on successful seal.
    ///
    /// # Errors
    ///
    /// Returns an error if the seal process fails (disk I/O, metadata write, etc.).
    pub async fn try_seal(
        &self,
        active: &mut ActiveSegment,
        elapsed_ms: u64,
        entries: &[SegmentIndexEntry],
    ) -> Result<Option<SegmentHandle>> {
        // Don't seal empty segments.
        if active.size() == 0 {
            return Ok(None);
        }

        // Check seal conditions.
        let should_seal = active.is_full() || elapsed_ms >= self.config.seal_timeout_ms;
        if !should_seal {
            return Ok(None);
        }

        self.seal(active, entries).await.map(Some)
    }

    /// Seals an active segment unconditionally.
    async fn seal(
        &self,
        active: &mut ActiveSegment,
        entries: &[SegmentIndexEntry],
    ) -> Result<SegmentHandle> {
        let segment_id = active.id();
        let tier = active.tier();
        let data = active.data().to_vec();
        let size = active.size();
        let blob_count = entries.len() as u32;

        // Build the blob index from the provided entries.
        let index = SegmentIndex::new(entries.to_vec())?;

        // Compute checksum (BLAKE3 of segment data).
        let checksum = blake3::hash(&data);
        let checksum_bytes: [u8; 32] = *checksum.as_bytes();

        // Serialize header and index.
        let header = SegmentHeader::new(segment_id, size, blob_count, size, checksum_bytes);
        let header_bytes = header.to_bytes();
        let index_bytes = index.to_bytes();

        // Write segment file: header + data + index.
        let path = self.config.data_dir.join(format!("{segment_id}.dat"));
        if let Some(parent) = path.parent() {
            tokio::fs::create_dir_all(parent).await?;
        }

        let mut file_data = Vec::with_capacity(header_bytes.len() + data.len() + index_bytes.len());
        file_data.extend_from_slice(&header_bytes);
        file_data.extend_from_slice(&data);
        file_data.extend_from_slice(&index_bytes);
        tokio::fs::write(&path, &file_data).await?;

        // Persist segment metadata.
        let meta = SegmentMetadata {
            segment_id,
            ec_k: 0, // set during EC encoding (Phase 3)
            ec_m: 0,
            size_tier: tier,
            merkle_root: None,
            storage_locations: smallvec::SmallVec::new(),
            sealed_at: Some(
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis() as i64,
            ),
        };
        self.metadata
            .put_segment(meta)
            .map_err(|e| Error::Io(std::io::Error::other(format!("metadata write failed: {e}"))))?;

        // Truncate the WAL (entries for this segment are no longer needed).
        let wal_pos = self.wal.global_position().await;
        self.wal.truncate(wal_pos).await?;

        Ok(SegmentHandle::new(segment_id, vec![]))
    }
}

