}

#[test]
fn delete_object_removes_it() {
    let dir = tempfile::tempdir().unwrap();
    let store = make_store(&dir);

    let meta = ObjectMetadata {
        object_key: test_key("tmp.dat"),
        size: 64,
        blake3_hash: None,
        chunks: smallvec::SmallVec::new(),
        inline_data: Some(bytes::Bytes::from_static(b"tmp")),
        created_at: 1_700_000_000_000,
        hlc: Hlc::zero(),
    };
    store.put_object(meta).unwrap();

    // Confirm it exists.
    assert!(store
        .get_object(&test_bucket(), &test_key("tmp.dat"))
        .unwrap()
        .is_some());

    store
        .delete_object(&test_bucket(), &test_key("tmp.dat"))
        .unwrap();

    // Confirm it is gone.
    assert!(store
        .get_object(&test_bucket(), &test_key("tmp.dat"))
        .unwrap()
        .is_none());
}

